-- Tryal Money PREVIEW: everything to test the Money tab with campaign footage, in ONE paste for the Supabase SQL editor.
-- GENERATED by expo/scripts/gen-apply-money-preview.mjs from the four migration files below: do not edit by hand.
--
-- Safe to run once, and again (every statement is idempotent). It does NOT run the birthdate lock-down (migration-money.sql only defines it).
-- It re-runs migration-money.sql and migration-money-board.sql in the right order, so it is also safe on a database that already has them:
-- the board file comes after the money file and puts the newer functions back. Do not paste migration-money.sql on its own afterwards.
-- Order: 1 post links, 2 money (flag, adult check), 3 money board (campaigns and rules), 4 money footage (uploads).
-- Runs as one script; if any statement fails nothing of this paste is kept, and the error names the line.
-- The check table at the end is the result you see.

-- ══════════════════════════════════════════════════════════════════════════════
-- PART: migration-post-links.sql
-- ══════════════════════════════════════════════════════════════════════════════
-- Tryal: LINKS ON POSTS (all posts, not only Money). Idempotent. Standalone: it needs only the base schema (posts), so it can ship before Money.
--
-- A post can carry ONE video link ("A specific video" in the composer). The post shows a "Watch on <platform>" button; the button never opens
-- the raw address, it opens a tracked short link (the `go` edge function, supabase/functions/go) that counts the tap and redirects.
--   * the address is validated here, on the server: https only, and only these sites: youtube.com, youtu.be, tiktok.com, instagram.com, x.com (and
--     twitter.com, www.twitter.com, mobile.twitter.com, shown as X), twitch.tv, open.spotify.com (subdomains of youtube / tiktok / instagram / x /
--     twitch are fine, e.g. www.youtube.com, vm.tiktok.com; not look-alikes)
--   * viewers see only the platform and the short code (columns on posts); the address itself is in post_links, readable by the post's owner only
--   * taps are counted per post per day (post_link_tap_days). The same device within 24 hours counts once. To do that the edge function sends
--     a salted hash of the caller (never the address, never the device); it sits in link_tap_seen for at most 48 hours and is then deleted.
--     Nothing about the person who tapped is kept: the counts are all that stays.
--   * the owner reads their own total with my_post_link_taps(post); apps cannot write any of these tables, and cannot call the two functions
--     the edge function uses (link_target, record_link_tap: service role only)
--   * a hidden or removed post's link stops working (link_target returns nothing)

-- ── 1. columns on posts (what a viewer needs) ─────────────────────────────────────────────────
alter table public.posts add column if not exists link_code text;
alter table public.posts add column if not exists link_platform text;
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'posts_link_platform_check') then
    alter table public.posts add constraint posts_link_platform_check
      check (link_platform is null or link_platform in ('youtube', 'tiktok', 'instagram', 'x', 'twitch', 'spotify'));
  end if;
end $$;
create unique index if not exists posts_link_code_uidx on public.posts (link_code) where link_code is not null;

-- ── 2. the address, the counts, the short-lived de-duplication ───────────────────────────────
create table if not exists public.post_links (
  post_id    uuid primary key references public.posts(id) on delete cascade,
  url        text not null check (char_length(url) <= 500),
  platform   text not null check (platform in ('youtube', 'tiktok', 'instagram', 'x', 'twitch', 'spotify')),
  code       text not null unique,
  created_at timestamptz not null default now()
);
create table if not exists public.post_link_tap_days (
  post_id uuid not null references public.posts(id) on delete cascade,
  day     date not null,
  taps    integer not null default 0 check (taps >= 0),
  primary key (post_id, day)
);
-- one row: how many counted taps one post's link may collect per hour (a script cannot inflate a count past this); raise it if a post goes viral
create table if not exists public.link_tap_config (
  id             boolean primary key default true check (id),
  max_per_hour   integer not null default 120 check (max_per_hour > 0)
);
insert into public.link_tap_config (id) values (true) on conflict do nothing;
alter table public.link_tap_config enable row level security;
revoke all on table public.link_tap_config from anon, authenticated;

create table if not exists public.link_tap_seen (
  code    text not null,
  fp      text not null check (char_length(fp) between 16 and 64),   -- a salted hash made by the edge function; nothing else
  seen_at timestamptz not null default now(),
  primary key (code, fp)
);
create index if not exists link_tap_seen_seen_at_idx on public.link_tap_seen (seen_at);

alter table public.post_links enable row level security;
alter table public.post_link_tap_days enable row level security;
alter table public.link_tap_seen enable row level security;
revoke all on table public.post_links, public.post_link_tap_days, public.link_tap_seen from anon, authenticated;
grant select on public.post_links to authenticated;
drop policy if exists post_links_owner_read on public.post_links;
create policy post_links_owner_read on public.post_links for select to authenticated
  using (exists (select 1 from public.posts p where p.id = post_links.post_id and p.user_id = auth.uid()));

-- ── 3. which sites, and which platform an address belongs to ──────────────────────────────────
-- null when the address is not allowed: not https, a user@host trick, a port, a look-alike host, whitespace, too long.
create or replace function public.link_platform_of(p_url text)
returns text
language plpgsql
immutable
as $$
declare
  u text := lower(btrim(coalesce(p_url, '')));
  h text;
begin
  if u = '' or char_length(u) > 500 or u ~ '\s' then return null; end if;
  h := substring(u from '^https://([a-z0-9][a-z0-9.-]*)(?:[/?#]|$)');
  if h is null then return null; end if;
  if h = 'youtube.com' or h like '%.youtube.com' or h = 'youtu.be' then return 'youtube'; end if;
  if h = 'tiktok.com' or h like '%.tiktok.com' then return 'tiktok'; end if;
  if h = 'instagram.com' or h like '%.instagram.com' then return 'instagram'; end if;
  if h = 'x.com' or h like '%.x.com' or h = 'twitter.com' or h = 'www.twitter.com' or h = 'mobile.twitter.com' then return 'x'; end if;
  if h = 'twitch.tv' or h like '%.twitch.tv' then return 'twitch'; end if;
  if h = 'open.spotify.com' then return 'spotify'; end if;
  return null;
end;
$$;

-- only the functions below may change link_code / link_platform (the SQL editor and the service role may too)
create or replace function public.posts_link_guard()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  trusted boolean := coalesce(nullif(current_setting('tryal.post_link_write', true), ''), '') = '1' or auth.uid() is null;
begin
  if tg_op = 'INSERT' then
    if (new.link_code is not null or new.link_platform is not null) and not trusted then
      raise exception 'a video link is added with set_post_video_link' using errcode = '42501';
    end if;
  elsif (new.link_code is distinct from old.link_code or new.link_platform is distinct from old.link_platform) and not trusted then
    raise exception 'a video link is changed with set_post_video_link' using errcode = '42501';
  end if;
  return new;
end;
$$;
drop trigger if exists posts_link_guard on public.posts;
create trigger posts_link_guard before insert or update of link_code, link_platform on public.posts
  for each row execute function public.posts_link_guard();

-- ── 4. what the app calls ─────────────────────────────────────────────────────────────────────
-- Add or change the video link on my own post. The code (the tracked short link) stays the same when the address changes.
create or replace function public.set_post_video_link(p_post uuid, p_url text)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  pr public.posts;
  pl text := public.link_platform_of(p_url);
  c text;
begin
  if me is null then raise exception 'not signed in' using errcode = '28000'; end if;
  select * into pr from public.posts where id = p_post and user_id = me;
  if not found then raise exception 'unknown post' using errcode = 'P0002'; end if;
  if pr.parent_post_id is not null then raise exception 'a reaction cannot carry a video link' using errcode = '22023'; end if;
  if pl is null then raise exception 'that link is not allowed: use YouTube, TikTok, Instagram, X, Twitch or Spotify' using errcode = '22023'; end if;
  select code into c from public.post_links where post_id = p_post;
  if c is null then
    loop
      c := substr(replace(gen_random_uuid()::text, '-', ''), 1, 10);
      exit when not exists (select 1 from public.post_links where code = c);
    end loop;
  end if;
  insert into public.post_links (post_id, url, platform, code) values (p_post, btrim(p_url), pl, c)
  on conflict (post_id) do update set url = excluded.url, platform = excluded.platform;
  perform set_config('tryal.post_link_write', '1', true);
  update public.posts set link_code = c, link_platform = pl where id = p_post;
  perform set_config('tryal.post_link_write', '', true);
  return c;
end;
$$;

create or replace function public.clear_post_video_link(p_post uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare me uuid := auth.uid();
begin
  if me is null then raise exception 'not signed in' using errcode = '28000'; end if;
  if not exists (select 1 from public.posts where id = p_post and user_id = me) then raise exception 'unknown post' using errcode = 'P0002'; end if;
  delete from public.post_links where post_id = p_post;
  perform set_config('tryal.post_link_write', '1', true);
  update public.posts set link_code = null, link_platform = null where id = p_post;
  perform set_config('tryal.post_link_write', '', true);
end;
$$;

-- "This post sent X people to your video": the total, to the post's owner only (anyone else gets 0)
create or replace function public.my_post_link_taps(p_post uuid)
returns integer
language sql
stable
security definer
set search_path = public
as $$
  select coalesce((select sum(d.taps)::integer from public.post_link_tap_days d join public.posts p on p.id = d.post_id
                    where d.post_id = p_post and p.user_id = auth.uid()), 0)
$$;

-- ── 5. what only the edge function calls (service role) ──────────────────────────────────────
-- the address behind a code, for a post that is still showing (not hidden or removed); nothing otherwise
create or replace function public.link_target(p_code text)
returns table (url text, post_id uuid)
language sql
stable
security definer
set search_path = public
as $$
  select l.url, l.post_id from public.post_links l join public.posts p on p.id = l.post_id
   where l.code = p_code and p.moderation_status = 'active'
$$;

-- Count one tap unless the same fingerprint already counted for this code in the last 24 hours, or this link already collected its hourly maximum
-- (link_tap_config.max_per_hour counted taps in the last hour: link_tap_seen rows touched in the last hour ARE this hour's counted taps). true = counted.
create or replace function public.record_link_tap(p_code text, p_fp text)
returns boolean
language plpgsql
security definer
set search_path = public
as $$
declare
  pid uuid;
  counted integer;
begin
  select l.post_id into pid from public.post_links l where l.code = p_code;
  if pid is null or p_fp is null or char_length(p_fp) not between 16 and 64 then return false; end if;
  if (select count(*) from public.link_tap_seen where code = p_code and seen_at > now() - interval '1 hour') >= (select max_per_hour from public.link_tap_config) then
    return false;
  end if;
  insert into public.link_tap_seen (code, fp, seen_at) values (p_code, p_fp, now())
  on conflict (code, fp) do update set seen_at = now()
    where public.link_tap_seen.seen_at < now() - interval '24 hours'
  returning 1 into counted;
  if counted is null then return false; end if;
  insert into public.post_link_tap_days (post_id, day, taps) values (pid, (now() at time zone 'utc')::date, 1)
  on conflict (post_id, day) do update set taps = public.post_link_tap_days.taps + 1;
  return true;
end;
$$;

-- the de-duplication hashes are kept for 48 hours at most
create or replace function public.link_taps_purge()
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare n integer;
begin
  delete from public.link_tap_seen where seen_at < now() - interval '48 hours';
  get diagnostics n = row_count;
  return n;
end;
$$;

-- weekly counts for the pitch metrics (weeks start on Monday, UTC); closed to apps
create or replace view public.link_taps_weekly as
  select date_trunc('week', day::timestamp)::date as week_start, sum(taps)::bigint as taps, count(distinct post_id)::bigint as posts_with_taps
    from public.post_link_tap_days group by 1;
revoke all on public.link_taps_weekly from anon, authenticated;

-- ── 6. who may call what ──────────────────────────────────────────────────────────────────────
revoke all on function public.link_platform_of(text), public.posts_link_guard(), public.set_post_video_link(uuid, text), public.clear_post_video_link(uuid),
  public.my_post_link_taps(uuid), public.link_target(text), public.record_link_tap(text, text), public.link_taps_purge() from public, anon, authenticated;
grant execute on function public.set_post_video_link(uuid, text), public.clear_post_video_link(uuid), public.my_post_link_taps(uuid) to authenticated;
grant execute on function public.link_target(text), public.record_link_tap(text, text), public.link_taps_purge() to service_role;

-- ── 7. the hourly purge ───────────────────────────────────────────────────────────────────────
do $$
begin
  if to_regnamespace('cron') is not null then
    perform cron.unschedule(j.jobid) from cron.job j where j.jobname = 'link-taps-purge';
    perform cron.schedule('link-taps-purge', '17 * * * *', 'select public.link_taps_purge()');
  end if;
exception when others then
  raise notice 'could not schedule link-taps-purge (%): run select public.link_taps_purge() by hand now and then', sqlerrm;
end $$;

-- ══════════════════════════════════════════════════════════════════════════════
-- PART: migration-money.sql
-- ══════════════════════════════════════════════════════════════════════════════
-- Tryal Money tab (v1). Idempotent; last in MIGRATIONS_ORDER.txt, after migration-sanctions.sql. See PLAN-CLIPS.md.
-- Built one step at a time; each step appends its own section below and is safe to re-run.
--
--   STEP 1  the database feature flag and the STRICT adult check
--
-- Everything Money does is behind the flag 'money' (app_flags). It is OFF for everyone except the allow-listed testers (the owner).
-- The adult check is strict: a known birthdate and 18+. 'unknown' (no birthdate) is NOT adult here, unlike friends_is_minor() elsewhere.
-- The functions that look at other people's age or flag state are internal (revoked from apps): an app could otherwise ask
-- "is this user an adult?" about anybody. The app only calls my_features().

-- ── 1. feature flags ─────────────────────────────────────────────────────────────────────
create table if not exists public.app_flags (
  key            text primary key,
  enabled        boolean not null default false,
  allow_user_ids uuid[] not null default '{}',     -- testers: the flag is on for them while enabled = false
  updated_at     timestamptz not null default now()
);
alter table public.app_flags enable row level security;
revoke all on table public.app_flags from anon, authenticated;

-- 'money': off for everyone except the owner (constants/debug.ts OWNER_USER_ID). Re-running never resets a flag that was changed:
-- the row is only created when missing, and the owner is only ADDED to the allow-list.
insert into public.app_flags (key, enabled, allow_user_ids) values ('money', false, array['aee21757-1ded-41a7-9392-bddbf0d657df']::uuid[])
  on conflict (key) do update
    set allow_user_ids = (select array(select distinct u from unnest(public.app_flags.allow_user_ids || excluded.allow_user_ids) u))
    where not (excluded.allow_user_ids <@ public.app_flags.allow_user_ids);

create or replace function public.flag_on(p_key text, p_user uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select p_user is not null and coalesce((select f.enabled or p_user = any (f.allow_user_ids) from public.app_flags f where f.key = p_key), false)
$$;

-- ── 2. the strict adult check ─────────────────────────────────────────────────────────────
-- A known birthdate and age_tier = 'adult' (18+). No birthdate, a teen or an under-13 is never adult here.
create or replace function public.money_is_adult(p_user uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (select 1 from public.profiles p where p.id = p_user and p.birthdate is not null and public.age_tier(p.birthdate) = 'adult')
$$;

-- May this account use Money at all (browse, create, submit)? Flag on, adult, and not suspended or banned.
create or replace function public.money_allowed(p_user uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select p_user is not null
     and public.flag_on('money', p_user)
     and public.money_is_adult(p_user)
     and not exists (select 1 from public.account_sanction_of(p_user))
$$;

-- What the app reads at launch:
--   money            show the tab at all (flag on, and not a KNOWN minor: a person with no birthdate yet still sees the tab so
--                    they can be asked for it on first visit; teens and under-13s never see it)
--   needs_birthdate  the flag is on for me and I have not given a birthdate: ask before anything else
--   allowed          I may actually use Money (money_allowed)
create or replace function public.my_features()
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  bd date;
  has_profile boolean;
  on_flag boolean;
begin
  if me is null then
    return jsonb_build_object('money', false, 'needs_birthdate', false, 'allowed', false);
  end if;
  select p.birthdate, true into bd, has_profile from public.profiles p where p.id = me;
  on_flag := public.flag_on('money', me);
  return jsonb_build_object(
    'money', coalesce(on_flag and has_profile and not exists (select 1 from public.account_sanction_of(me)) and (bd is null or public.age_tier(bd) = 'adult'), false),
    'needs_birthdate', coalesce(on_flag and has_profile and bd is null, false),
    'allowed', public.money_allowed(me)
  );
end;
$$;

revoke all on function public.flag_on(text, uuid), public.money_is_adult(uuid), public.money_allowed(uuid) from public, anon, authenticated;
revoke all on function public.my_features() from public, anon;
grant execute on function public.my_features() to authenticated;

-- ══ STEP 2: birthdate collection and lock-down ═══════════════════════════════════════════
-- Money is 18+. The birthdate is collected at sign-up (new users) or on the first Money visit (existing users), then it is
-- (a) written only through set_my_birthdate / the sign-up trigger, never by a direct profile write, (b) set once: a person can
-- not move it later to become an adult, and (c) unreadable by other people once money_apply_birthdate_lockdown() has run.
-- That last part is deliberately NOT automatic: profiles is publicly readable with a table-wide select grant and builds 48/49
-- select `birthdate` from it, so revoking the column would break their profile load. Until the owner runs the lock-down, the
-- app never stores a birthdate (set_my_birthdate refuses, and the sign-up trigger ignores the one in the metadata), so a date
-- is never sitting in a publicly readable column.

alter table public.profiles add column if not exists birthdate_set_at timestamptz;

-- Who may write the birthdate column: the sign-up trigger and set_my_birthdate (a transaction-local flag they set), an admin,
-- and the service role / SQL editor (no JWT user). Everyone else: refused. A set date can only be changed by an admin.
create or replace function public.birthdate_write_guard()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  trusted boolean := coalesce(nullif(current_setting('tryal.birthdate_write', true), ''), '') = '1'
                     or auth.uid() is null
                     or public.mod_is_admin();
begin
  if tg_op = 'INSERT' then
    if new.birthdate is not null and not trusted then
      raise exception 'birthdate can only be set through the app flow' using errcode = '42501';
    end if;
    if new.birthdate is not null then new.birthdate_set_at := coalesce(new.birthdate_set_at, now()); end if;
    return new;
  end if;
  if new.birthdate is distinct from old.birthdate then
    if not trusted then
      raise exception 'birthdate can only be set through the app flow' using errcode = '42501';
    end if;
    if old.birthdate is not null and not (auth.uid() is null or public.mod_is_admin()) then
      raise exception 'birthdate is already set' using errcode = '42501';
    end if;
    new.birthdate_set_at := now();
  end if;
  if new.birthdate_set_at is distinct from old.birthdate_set_at and not (auth.uid() is null or public.mod_is_admin()) then
    new.birthdate_set_at := old.birthdate_set_at;
  end if;
  return new;
end;
$$;

drop trigger if exists profiles_birthdate_guard on public.profiles;
create trigger profiles_birthdate_guard
  before insert or update on public.profiles
  for each row execute function public.birthdate_write_guard();

-- Has the owner applied the lock-down? (a flag row, written only by money_apply_birthdate_lockdown)
insert into public.app_flags (key, enabled, allow_user_ids)
values ('birthdate_lockdown', false, '{}')
on conflict (key) do nothing;

-- Text -> date, or null when it is not a real calendar date (never raises).
create or replace function public.birthdate_parse(p text)
returns date
language plpgsql
immutable
as $$
begin
  if p is null or p !~ '^\d{4}-\d{2}-\d{2}$' then return null; end if;
  return p::date;
exception when others then
  return null;
end;
$$;

-- A date that makes sense: not in the future, not before 1900.
create or replace function public.birthdate_is_valid(p date)
returns boolean
language sql
immutable
as $$ select p is not null and p <= current_date and p >= date '1900-01-01' $$;

-- The app calls this once, on the first Money visit. Returns the age tier ('under_13' | 'teen' | 'adult').
--   * refuses until the lock-down is applied (so the date is never publicly readable)
--   * refuses an invalid date, and a second set (only an admin can correct a date)
--   * stores the date even for a minor (a minor is then a known minor everywhere age_tier is used), but never lets Money open
create or replace function public.set_my_birthdate(p_birthdate date)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  cur date;
begin
  if me is null then raise exception 'not signed in' using errcode = '28000'; end if;
  if not exists (select 1 from public.app_flags where key = 'birthdate_lockdown' and enabled) then
    raise exception 'birthdate is not available yet' using errcode = '55000';
  end if;
  if not public.birthdate_is_valid(p_birthdate) then raise exception 'invalid birthdate' using errcode = '22007'; end if;
  select birthdate into cur from public.profiles where id = me;
  if not found then raise exception 'no profile' using errcode = 'P0002'; end if;
  if cur is not null then raise exception 'birthdate is already set' using errcode = '42501'; end if;
  perform set_config('tryal.birthdate_write', '1', true);
  update public.profiles set birthdate = p_birthdate where id = me;
  perform set_config('tryal.birthdate_write', '', true);
  return public.age_tier(p_birthdate);
end;
$$;

-- My own birthdate, for the client's age checks (the column itself is unreadable after the lock-down).
create or replace function public.my_birthdate()
returns date
language sql
stable
security definer
set search_path = public
as $$ select p.birthdate from public.profiles p where p.id = auth.uid() $$;

-- Sign-up: the profile row is created from the auth metadata. The metadata birthdate is copied only when the lock-down is applied
-- and the value is valid; otherwise it is ignored (the person is asked on their first Money visit instead). Same inserts as before.
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer set search_path = public
as $$
declare
  bd date;
begin
  if exists (select 1 from public.app_flags where key = 'birthdate_lockdown' and enabled) then
    bd := public.birthdate_parse(new.raw_user_meta_data->>'birthdate');
    if not public.birthdate_is_valid(bd) then bd := null; end if;
  end if;
  perform set_config('tryal.birthdate_write', '1', true);
  insert into public.profiles (id, username, display_name, birthdate)
  values (
    new.id,
    coalesce(new.raw_user_meta_data->>'username', 'dropper_' || left(new.id::text, 8)),
    coalesce(new.raw_user_meta_data->>'username', 'dropper_' || left(new.id::text, 8)),
    bd
  )
  on conflict (id) do nothing;
  perform set_config('tryal.birthdate_write', '', true);
  return new;
end;
$$;

-- The owner's switch. Run it in the SQL editor ONLY once no build that selects `birthdate` from profiles is in use (48/49 do):
--   select public.money_apply_birthdate_lockdown();
-- It (1) copies a birthdate from the sign-up metadata onto profiles that have none, (2) takes the column away from anon and
-- authenticated (every other column stays readable, exactly as before), (3) turns the birthdate_lockdown flag on.
-- Re-run public.money_refresh_profile_grants() after ANY migration that adds a column to profiles (new columns are not granted).
create or replace function public.money_refresh_profile_grants()
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  cols text;
  lock_on boolean := exists (select 1 from public.app_flags where key = 'birthdate_lockdown' and enabled);
begin
  -- readable by everyone, as before, except: money_banned and birthdate_set_at always; birthdate once the lock-down is on
  select string_agg(quote_ident(column_name), ', ' order by ordinal_position) into cols
  from information_schema.columns
  where table_schema = 'public' and table_name = 'profiles'
    and column_name not in ('money_banned', 'birthdate_set_at')
    and (column_name <> 'birthdate' or not lock_on);
  execute 'revoke select on public.profiles from anon, authenticated';
  execute format('grant select (%s) on public.profiles to anon, authenticated', cols);
  return cols;
end;
$$;

create or replace function public.money_apply_birthdate_lockdown()
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  copied int := 0;
begin
  if auth.uid() is not null and not public.mod_is_admin() then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  perform set_config('tryal.birthdate_write', '1', true);
  with src as (
    select p.id, public.birthdate_parse(u.raw_user_meta_data->>'birthdate') as bd
    from public.profiles p
    join auth.users u on u.id = p.id
    where p.birthdate is null
  ), upd as (
    update public.profiles p set birthdate = s.bd
    from src s where p.id = s.id and public.birthdate_is_valid(s.bd)
    returning 1
  )
  select count(*) into copied from upd;
  perform set_config('tryal.birthdate_write', '', true);
  update public.app_flags set enabled = true where key = 'birthdate_lockdown';   -- first: the grants below read it
  perform public.money_refresh_profile_grants();
  return format('lockdown applied; %s birthdates copied from sign-up metadata', copied);
end;
$$;

revoke all on function public.birthdate_write_guard(), public.birthdate_is_valid(date), public.birthdate_parse(text), public.money_refresh_profile_grants(), public.money_apply_birthdate_lockdown() from public, anon, authenticated;
revoke all on function public.set_my_birthdate(date), public.my_birthdate() from public, anon;
grant execute on function public.set_my_birthdate(date), public.my_birthdate() to authenticated;

-- ══════════════════════════════════════════════════════════════════════════════
-- PART: migration-money-board.sql
-- ══════════════════════════════════════════════════════════════════════════════
-- Tryal Money tab v1 "job board" (MONEY_TAB_SPEC.md). Idempotent; applied AFTER migration-money.sql (the flag, the adult check, the birthdate
-- lock-down). v1 moves NO money in the app: creators post campaigns, clippers make clips, the creator pays outside the app, Tryal does
-- the math, tracks who paid and enforces reputation.
--
--   STEP 1  schema, RLS and triggers (spec sections 1, 11)
--
-- HOW IT IS CLOSED
--   * every money table has row level security and NO write grant for apps: all writes go through the SECURITY DEFINER functions below
--     (and, in later steps, the ones the spec lists: links, proof, approve, dispute, paid/received, reviews)
--   * every read policy requires money_ready(): the money flag, a known 18+ birthdate, not sanctioned, not money_banned, and the walkthrough
--     + agreement for the current version finished. Under-18s, banned and not-onboarded accounts read nothing, whatever the app shows.
--   * a block hides the other person's campaigns and submissions (either direction) and stops them from joining; a clipper keeps seeing
--     their OWN submissions even if the creator blocked them, because they may still be owed money
--   * the campaign's payment handle is a column apps cannot select (only members get it, through campaign_payment_info())
-- WHAT IS NOT HERE YET (later steps): the app screens, links / proof / approval / payment RPCs, the scheduled jobs, notifications, the
-- messaging thread on join, and the editor-session proof for edited_in_tryal (until then it is always false).

-- ══ 0. profiles.money_banned ════════════════════════════════════════════════════════════════
alter table public.profiles add column if not exists money_banned boolean not null default false;

-- only an admin / the SQL editor may change it (a user could otherwise lift their own ban)
create or replace function public.profiles_money_banned_guard()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if tg_op = 'INSERT' then
    if new.money_banned and auth.uid() is not null and not public.mod_is_admin() then
      raise exception 'not allowed' using errcode = '42501';
    end if;
    return new;
  end if;
  if new.money_banned is distinct from old.money_banned and auth.uid() is not null and not public.mod_is_admin() then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  return new;
end;
$$;
drop trigger if exists profiles_money_banned_guard on public.profiles;
create trigger profiles_money_banned_guard before insert or update on public.profiles
  for each row execute function public.profiles_money_banned_guard();

-- ══ 1. configuration (closed; one row) ═════════════════════════════════════════════════════
create table if not exists public.money_config (
  id                  boolean primary key default true check (id),
  agreement_version   integer not null default 1,      -- bump to make everybody read and tick the agreement again
  approval_hours      integer not null default 48,     -- creator's window to approve / dispute before auto-approval
  payment_days        integer not null default 3,      -- pay within this many days of approval
  proof_grace_days    integer not null default 3,      -- proof due this long after the view window ends
  review_reveal_days  integer not null default 7,      -- blind reviews publish after this long
  max_proof_images    integer not null default 3,
  max_clip_seconds    integer not null default 60,
  late_strikes_to_ban integer not null default 2
);
insert into public.money_config (id) values (true) on conflict do nothing;
alter table public.money_config enable row level security;
revoke all on table public.money_config from anon, authenticated;

-- ══ 2. who may use Money: banned, onboarded, ready ═════════════════════════════════════════
-- money_allowed (migration-money.sql) now also requires "not money_banned".
create or replace function public.money_allowed(p_user uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select p_user is not null
     and public.flag_on('money', p_user)
     and public.money_is_adult(p_user)
     and not exists (select 1 from public.profiles p where p.id = p_user and p.money_banned)
     and not exists (select 1 from public.account_sanction_of(p_user))
$$;

-- the walkthrough and agreement, closed table (never on public profiles)
create table if not exists public.money_profiles (
  user_id                  uuid primary key references public.profiles(id) on delete cascade,
  money_role               text not null check (money_role in ('creator', 'clipper', 'both')),
  money_onboarded_at       timestamptz,
  money_agreement_version  integer,
  agreed_rules             jsonb not null default '[]'::jsonb,   -- the checkboxes ticked
  created_at               timestamptz not null default now(),
  updated_at               timestamptz not null default now()
);
alter table public.money_profiles enable row level security;
revoke all on table public.money_profiles from anon, authenticated;

-- allowed AND finished the walkthrough for the current agreement version. Every table policy and every RPC below uses this.
create or replace function public.money_ready(p_user uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select public.money_allowed(p_user)
     and exists (select 1 from public.money_profiles mp, public.money_config c
                 where mp.user_id = p_user and mp.money_onboarded_at is not null and mp.money_agreement_version = c.agreement_version)
$$;

create or replace function public.money_role_of(p_user uuid)
returns text
language sql
stable
security definer
set search_path = public
as $$ select mp.money_role from public.money_profiles mp where mp.user_id = p_user $$;

-- the rules a person must tick, per role (one checkbox per rule). 'campaign_messaging' = "Campaign members can message each other about the
-- work, even if your messages are set to nobody. You can still block anyone." (see section 17)
create or replace function public.money_required_rules(p_role text)
returns text[]
language sql
immutable
as $$
  select case p_role
    when 'creator' then array['pay_on_time', 'terms_freeze', 'auto_approval_48h', 'not_part_of_payment', 'own_footage_rights', 'campaign_messaging']
    when 'clipper' then array['only_real_views', 'submit_through_tryal', 'upload_proof_on_time', 'footage_use', 'not_part_of_payment', 'campaign_messaging']
    when 'both'    then array['pay_on_time', 'terms_freeze', 'auto_approval_48h', 'not_part_of_payment', 'own_footage_rights',
                              'only_real_views', 'submit_through_tryal', 'upload_proof_on_time', 'footage_use', 'campaign_messaging']
  end
$$;

-- Finish (or redo) the walkthrough. Every required rule must be ticked: the server checks, not the screen.
create or replace function public.money_complete_onboarding(p_role text, p_rules text[])
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  need text[];
  ver integer;
begin
  if me is null then raise exception 'not signed in' using errcode = '28000'; end if;
  if not public.money_allowed(me) then raise exception 'Money is not available for this account' using errcode = '42501'; end if;
  if p_role is null or p_role not in ('creator', 'clipper', 'both') then raise exception 'pick creator, clipper or both' using errcode = '22023'; end if;
  need := public.money_required_rules(p_role);
  if not (coalesce(p_rules, '{}') @> need) then raise exception 'tick every rule to continue' using errcode = '22023'; end if;
  select agreement_version into ver from public.money_config;
  insert into public.money_profiles (user_id, money_role, money_onboarded_at, money_agreement_version, agreed_rules)
  values (me, p_role, now(), ver, to_jsonb(need))
  on conflict (user_id) do update
    set money_role = excluded.money_role, money_onboarded_at = now(), money_agreement_version = ver,
        agreed_rules = excluded.agreed_rules, updated_at = now();
  return public.my_money_profile();
end;
$$;

create or replace function public.my_money_profile()
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  mp public.money_profiles;
  cur integer;
begin
  if me is null then return jsonb_build_object('allowed', false, 'ready', false); end if;
  select agreement_version into cur from public.money_config;
  select * into mp from public.money_profiles where user_id = me;
  return jsonb_build_object(
    'allowed', public.money_allowed(me),
    'ready', public.money_ready(me),
    'role', mp.money_role,
    'onboarded_at', mp.money_onboarded_at,
    'agreement_version', mp.money_agreement_version,
    'current_agreement_version', cur,
    'needs_onboarding', public.money_allowed(me) and not public.money_ready(me),
    'banned', coalesce((select p.money_banned from public.profiles p where p.id = me), false)
  );
end;
$$;

-- what the app reads at launch (migration-money.sql's, plus banned / onboarding)
create or replace function public.my_features()
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  bd date;
  has_profile boolean;
  banned boolean;
  on_flag boolean;
begin
  if me is null then
    return jsonb_build_object('money', false, 'needs_birthdate', false, 'allowed', false, 'ready', false, 'needs_onboarding', false, 'banned', false);
  end if;
  select p.birthdate, true, p.money_banned into bd, has_profile, banned from public.profiles p where p.id = me;
  on_flag := public.flag_on('money', me);
  return jsonb_build_object(
    'money', coalesce(on_flag and has_profile and not banned and not exists (select 1 from public.account_sanction_of(me)) and (bd is null or public.age_tier(bd) = 'adult'), false),
    'needs_birthdate', coalesce(on_flag and has_profile and not banned and bd is null, false),
    'allowed', public.money_allowed(me),
    'ready', public.money_ready(me),
    'needs_onboarding', public.money_allowed(me) and not public.money_ready(me),
    'banned', coalesce(banned, false)
  );
end;
$$;

-- ══ 3. campaigns ═════════════════════════════════════════════════════════════════════════════
create table if not exists public.campaigns (
  id                    uuid primary key default gen_random_uuid(),
  creator_id            uuid not null references public.profiles(id) on delete cascade,
  title                 text not null check (char_length(title) between 1 and 60),
  description           text not null check (char_length(description) between 1 and 1000),
  footage_url           text not null,
  rate_per_1k           numeric(10,2) not null check (rate_per_1k > 0 and rate_per_1k <= 1000),
  cap_per_clip          numeric(10,2) not null check (cap_per_clip > 0 and cap_per_clip <= 100000),
  total_budget          numeric(12,2) not null check (total_budget > 0 and total_budget <= 10000000),
  guaranteed_per_clip   numeric(10,2) not null default 0 check (guaranteed_per_clip >= 0 and guaranteed_per_clip <= 100000),
  platforms             text[] not null check (cardinality(platforms) between 1 and 4),
  view_window_days      integer not null default 7 check (view_window_days between 3 and 14),
  min_views             integer not null default 1000 check (min_views >= 0),
  payment_method        text not null check (payment_method in ('paypal', 'venmo', 'cashapp')),
  payment_handle        text not null,                          -- plain text only; apps cannot select this column (campaign_payment_info)
  deadline              timestamptz not null,
  max_clips_per_clipper integer not null default 5 check (max_clips_per_clipper between 1 and 50),
  status                text not null default 'open' check (status in ('open', 'paused', 'closed')),
  paused_reason         text check (paused_reason is null or paused_reason in ('overdue_payment', 'creator_banned', 'creator', 'admin')),
  closed_reason         text check (closed_reason is null or closed_reason in ('creator', 'deadline', 'budget', 'admin')),
  terms_frozen_at       timestamptz,
  budget_committed      numeric(12,2) not null default 0,
  agreement_version     integer not null,                       -- the Campaign Agreement the creator accepted
  creator_agreed_at     timestamptz not null default now(),
  created_at            timestamptz not null default now(),
  check (guaranteed_per_clip + cap_per_clip <= total_budget)
);
-- footage is uploaded into Tryal (migration-money-footage.sql), so footage_url (the old Drive / Dropbox link) is no longer needed; the optional
-- "Full video" link (a frozen term) is full_video_url; closed_at starts the 30-day footage deletion clock
alter table public.campaigns alter column footage_url drop not null;
alter table public.campaigns add column if not exists full_video_url text;
alter table public.campaigns add column if not exists closed_at timestamptz;
alter table public.campaigns add column if not exists budget_left numeric(12,2) generated always as (total_budget - budget_committed) stored;   -- what Browse shows, always live
create index if not exists campaigns_creator_idx on public.campaigns (creator_id);
create index if not exists campaigns_open_idx on public.campaigns (created_at desc) where status = 'open';

-- host of an https URL, lower case; null for anything else (http, a user@host trick, a port, no host)
create or replace function public.money_url_host(p_url text)
returns text
language sql
immutable
as $$ select substring(lower(btrim(p_url)) from '^https://([a-z0-9][a-z0-9.-]*)(?:[/?#]|$)') $$;

create or replace function public.money_is_footage_host(p_host text)
returns boolean
language sql
immutable
as $$ select p_host is not null and (p_host = 'drive.google.com' or p_host = 'dropbox.com' or p_host like '%.dropbox.com') $$;

-- a payment handle is plain text: an email, @name or $cashtag. No URL, no deep link, no "paypal.me/...", no spaces.
create or replace function public.money_handle_ok(p_handle text)
returns boolean
language sql
immutable
as $$
  select p_handle is not null
     and p_handle ~ '^[A-Za-z0-9@$._+-]{2,64}$'
     and p_handle ~ '[A-Za-z0-9]'
     and lower(p_handle) !~ '(paypal\.me|paypal\.com|venmo\.com|cash\.app|cash\.me|https?|www\.)'
$$;

create or replace function public.campaigns_validate()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  p text;
  role_ text;
  cfg public.money_config;
begin
  new.title := btrim(new.title);
  new.description := btrim(new.description);
  new.footage_url := btrim(new.footage_url);
  new.payment_handle := btrim(new.payment_handle);
  select array_agg(distinct lower(x) order by lower(x)) into new.platforms from unnest(new.platforms) x;
  foreach p in array new.platforms loop
    if p not in ('tiktok', 'instagram', 'youtube', 'x') then raise exception 'unknown platform' using errcode = '22023'; end if;
  end loop;
  -- (footage_url is the old Drive / Dropbox link: only checked when somebody still sets it; footage is uploaded now)
  if new.footage_url is not null and (tg_op = 'INSERT' or new.footage_url is distinct from old.footage_url) then
    if not public.money_is_footage_host(public.money_url_host(new.footage_url)) then
      raise exception 'footage must be a Google Drive or Dropbox share link' using errcode = '22023';
    end if;
  end if;
  -- the optional "Full video" link: one of the allowed sites (public.link_platform_of, migration-post-links.sql)
  if new.full_video_url is not null then
    new.full_video_url := btrim(new.full_video_url);
    if tg_op = 'INSERT' or new.full_video_url is distinct from old.full_video_url then
      if public.link_platform_of(new.full_video_url) is null then
        raise exception 'the Full video link must be a YouTube, TikTok, Instagram, X, Twitch or Spotify link' using errcode = '22023';
      end if;
    end if;
  end if;
  if tg_op = 'INSERT' or new.payment_handle is distinct from old.payment_handle then
    if not public.money_handle_ok(new.payment_handle) then
      raise exception 'the payment handle must be plain text (an email, @name or $cashtag), not a link' using errcode = '22023';
    end if;
  end if;
  if tg_op = 'INSERT' or new.title is distinct from old.title then perform public.text_check(new.title); end if;
  if tg_op = 'INSERT' or new.description is distinct from old.description then perform public.text_check(new.description); end if;
  if tg_op = 'INSERT' then
    if new.deadline <= now() + interval '1 hour' or new.deadline > now() + interval '366 days' then
      raise exception 'the deadline must be between 1 hour and a year from now' using errcode = '22023';
    end if;
    -- the creator must be able to use Money, be a creator, and have nothing overdue (spec 8). The check applies to SQL-editor
    -- inserts as well; auth.uid() is null there, so only the rules that do not need a user are skipped.
    if auth.uid() is not null then
      if not public.money_ready(new.creator_id) then raise exception 'Money is not available for this account' using errcode = '42501'; end if;
      role_ := public.money_role_of(new.creator_id);
      if role_ not in ('creator', 'both') then raise exception 'pick the creator role to post campaigns' using errcode = '42501'; end if;
    end if;
    if exists (select 1 from public.campaigns c where c.creator_id = new.creator_id and c.status = 'paused' and c.paused_reason = 'overdue_payment') then
      raise exception 'you have an overdue payment: resolve it before posting a new campaign' using errcode = '42501';
    end if;
    select * into cfg from public.money_config;
    new.agreement_version := coalesce(new.agreement_version, cfg.agreement_version);
  end if;
  return new;
end;
$$;
drop trigger if exists campaigns_validate on public.campaigns;
create trigger campaigns_validate before insert or update on public.campaigns
  for each row execute function public.campaigns_validate();

-- closed_at: when a campaign closes (the creator, the budget or an admin) the 30-day footage deletion clock starts
create or replace function public.campaigns_closed_at()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.status = 'closed' and old.status is distinct from 'closed' then new.closed_at := coalesce(new.closed_at, now()); end if;
  return new;
end;
$$;
drop trigger if exists campaigns_closed_at on public.campaigns;
create trigger campaigns_closed_at before update of status on public.campaigns
  for each row execute function public.campaigns_closed_at();
update public.campaigns set closed_at = coalesce(closed_at, now()) where status = 'closed' and closed_at is null;

-- The terms freeze when the first clipper joins (terms_frozen_at). From then on none of these columns can change, by anyone with an
-- account; the owner in the SQL editor (no signed-in user) can still correct something by hand. Status and the budget numbers are the
-- system's and stay editable.
create or replace function public.campaigns_freeze_guard()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.creator_id is distinct from old.creator_id and auth.uid() is not null then
    raise exception 'a campaign cannot change hands' using errcode = '42501';
  end if;
  if old.terms_frozen_at is not null and auth.uid() is not null then
    if new.terms_frozen_at is distinct from old.terms_frozen_at then
      raise exception 'terms are frozen' using errcode = '42501';
    end if;
    if (new.title, new.description, new.footage_url, new.full_video_url, new.rate_per_1k, new.cap_per_clip, new.guaranteed_per_clip,
        new.platforms, new.view_window_days, new.min_views, new.payment_method, new.payment_handle, new.deadline, new.max_clips_per_clipper)
       is distinct from
       (old.title, old.description, old.footage_url, old.full_video_url, old.rate_per_1k, old.cap_per_clip, old.guaranteed_per_clip,
        old.platforms, old.view_window_days, old.min_views, old.payment_method, old.payment_handle, old.deadline, old.max_clips_per_clipper) then
      raise exception 'terms are frozen once the first clipper has joined' using errcode = '42501';
    end if;
    -- the one change allowed after the freeze: MORE budget, and only through money_increase_budget (which sets the flag below)
    if new.total_budget is distinct from old.total_budget then
      if new.total_budget < old.total_budget then
        raise exception 'the budget can only go up once terms are frozen' using errcode = '42501';
      end if;
      if coalesce(nullif(current_setting('tryal.budget_increase', true), ''), '') <> '1' then
        raise exception 'terms are frozen once the first clipper has joined' using errcode = '42501';
      end if;
    end if;
  end if;
  return new;
end;
$$;
drop trigger if exists campaigns_freeze_guard on public.campaigns;
create trigger campaigns_freeze_guard before update on public.campaigns
  for each row execute function public.campaigns_freeze_guard();

-- ══ 4. members, submissions, links ═══════════════════════════════════════════════════════════
create table if not exists public.campaign_members (
  campaign_id   uuid not null references public.campaigns(id) on delete cascade,
  clipper_id    uuid not null references public.profiles(id) on delete cascade,
  joined_at     timestamptz not null default now(),
  agreed_terms  jsonb not null,                          -- the terms and agreement version the clipper saw when joining
  primary key (campaign_id, clipper_id)
);
create index if not exists campaign_members_clipper_idx on public.campaign_members (clipper_id);

create table if not exists public.campaign_submissions (
  id                 uuid primary key default gen_random_uuid(),
  campaign_id        uuid not null references public.campaigns(id) on delete cascade,
  clipper_id         uuid not null references public.profiles(id) on delete cascade,
  post_id            uuid references public.posts(id) on delete set null,      -- the Tryal post; null once it is deleted
  post_outcome       text not null default 'testing' check (post_outcome in ('queued', 'testing', 'survived', 'unjudged', 'failed', 'removed', 'ended')),
  status             text not null default 'posted' check (status in ('posted', 'awaiting_proof', 'awaiting_approval', 'disputed', 'approved', 'paid', 'unpaid', 'rejected')),
  views_claimed      integer check (views_claimed is null or views_claimed >= 0),
  likes_claimed      integer check (likes_claimed is null or likes_claimed >= 0),
  proof_paths        text[] not null default '{}' check (cardinality(proof_paths) <= 3),   -- 1-3 screenshots (the spec's proof_path)
  proof_uploaded_at  timestamptz,
  proof_waived       boolean not null default false,        -- proof was 3 days late: only the guaranteed amount is earned
  external_posted_at timestamptz,                           -- the view window starts here (first external link)
  window_ends_at     timestamptz,
  amount_owed        numeric(12,2),                          -- computed by money_compute_owed; apps cannot write it
  approved_at        timestamptz,
  approval_source    text check (approval_source is null or approval_source in ('creator', 'auto', 'admin')),
  payment_due_at     timestamptz,
  paid_marked_at     timestamptz,                            -- the creator's "I paid"
  received_at        timestamptz,                            -- the clipper's "Payment received": this is what counts
  flagged            boolean not null default false,
  admin_resolved_at  timestamptz,                            -- an admin settled a dispute or a "not paid" case (unlocks reviews)
  created_at         timestamptz not null default now()
);
create unique index if not exists campaign_submissions_post_uidx on public.campaign_submissions (post_id) where post_id is not null;
create index if not exists campaign_submissions_campaign_idx on public.campaign_submissions (campaign_id, clipper_id);
create index if not exists campaign_submissions_clipper_idx on public.campaign_submissions (clipper_id);

create table if not exists public.submission_links (
  id              uuid primary key default gen_random_uuid(),
  submission_id   uuid not null references public.campaign_submissions(id) on delete cascade,
  platform        text not null check (platform in ('tiktok', 'instagram', 'youtube', 'x')),
  url             text not null check (char_length(url) <= 500),
  account_age_days integer check (account_age_days is null or account_age_days >= 0),   -- entered by the clipper (fraud flag input)
  posted_at       timestamptz not null default now(),
  unique (submission_id, url)
);

create table if not exists public.submission_disputes (
  id             uuid primary key default gen_random_uuid(),
  submission_id  uuid not null references public.campaign_submissions(id) on delete cascade,
  raised_by      uuid not null references public.profiles(id) on delete cascade,
  reason         text not null check (reason in ('fake_views', 'wrong_content', 'not_my_campaign', 'proof_mismatch', 'other')),
  note           text check (note is null or char_length(note) <= 500),
  resolution     text check (resolution is null or resolution in ('approved', 'adjusted', 'rejected')),
  resolved_by    uuid references public.profiles(id) on delete set null,
  resolved_at    timestamptz,
  created_at     timestamptz not null default now()
);
create unique index if not exists submission_disputes_open_uidx on public.submission_disputes (submission_id) where resolved_at is null;

-- "Not paid": opened by the clipper, the creator may add a payment receipt screenshot, the clipper responds, an admin decides.
create table if not exists public.payment_cases (
  id                 uuid primary key default gen_random_uuid(),
  submission_id      uuid not null references public.campaign_submissions(id) on delete cascade,
  opened_by          uuid not null references public.profiles(id) on delete cascade,
  clipper_note       text check (clipper_note is null or char_length(clipper_note) <= 500),
  creator_receipt_paths text[] not null default '{}' check (cardinality(creator_receipt_paths) <= 3),
  creator_note       text check (creator_note is null or char_length(creator_note) <= 500),
  clipper_response   text check (clipper_response is null or char_length(clipper_response) <= 500),
  resolution         text check (resolution is null or resolution in ('paid', 'non_payment_confirmed', 'dismissed')),
  resolved_by        uuid references public.profiles(id) on delete set null,
  resolved_at        timestamptz,
  created_at         timestamptz not null default now()
);
create unique index if not exists payment_cases_open_uidx on public.payment_cases (submission_id) where resolved_at is null;

-- ══ 5. reviews and strikes ═══════════════════════════════════════════════════════════════════
create table if not exists public.money_reviews (
  id             uuid primary key default gen_random_uuid(),
  submission_id  uuid not null references public.campaign_submissions(id) on delete cascade,
  reviewer_id    uuid not null references public.profiles(id) on delete cascade,
  reviewee_id    uuid not null references public.profiles(id) on delete cascade,
  role           text not null check (role in ('creator', 'clipper')),      -- the REVIEWER's role in the deal
  stars          integer not null check (stars between 1 and 5),
  tags           text[] not null default '{}' check (cardinality(tags) <= 6),
  comment        text check (comment is null or char_length(comment) <= 280),
  published_at   timestamptz,                                               -- null until both are in or the reveal days pass
  created_at     timestamptz not null default now(),
  unique (submission_id, role),
  check (reviewer_id <> reviewee_id)
);
create index if not exists money_reviews_reviewee_idx on public.money_reviews (reviewee_id) where published_at is not null;

create table if not exists public.money_strikes (
  id             uuid primary key default gen_random_uuid(),
  user_id        uuid not null references public.profiles(id) on delete cascade,
  kind           text not null check (kind in ('late_payment', 'non_payment', 'fake_views')),
  submission_id  uuid references public.campaign_submissions(id) on delete set null,
  note           text,
  created_at     timestamptz not null default now()
);
create index if not exists money_strikes_user_idx on public.money_strikes (user_id, kind);

-- 2 late payments, or 1 confirmed non-payment, or confirmed fake views: money_banned, and a banned creator's campaigns pause.
create or replace function public.money_strike_apply()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  cfg public.money_config;
  late integer;
  ban boolean := false;
begin
  select * into cfg from public.money_config;
  if new.kind in ('non_payment', 'fake_views') then
    ban := true;
  else
    select count(*) into late from public.money_strikes where user_id = new.user_id and kind = 'late_payment';
    ban := late >= cfg.late_strikes_to_ban;
  end if;
  if ban then
    update public.profiles set money_banned = true where id = new.user_id and not money_banned;
    if found then
      insert into public.moderation_log (actor, action, target_user, detail)
      values (null, 'money_ban', new.user_id, jsonb_build_object('strike', new.kind, 'strike_id', new.id));
    end if;
    update public.campaigns set status = 'paused', paused_reason = 'creator_banned'
     where creator_id = new.user_id and status = 'open';
  end if;
  return new;
end;
$$;
drop trigger if exists money_strike_apply on public.money_strikes;
create trigger money_strike_apply after insert on public.money_strikes
  for each row execute function public.money_strike_apply();

-- ══ 6. posts: campaign, clipped_for, edited_in_tryal ═════════════════════════════════════════
alter table public.posts add column if not exists campaign_id uuid references public.campaigns(id) on delete set null;
alter table public.posts add column if not exists clipped_for_user_id uuid references public.profiles(id) on delete set null;
alter table public.posts add column if not exists edited_in_tryal boolean not null default false;
create index if not exists posts_campaign_idx on public.posts (campaign_id) where campaign_id is not null;

-- ══ 7. helpers for the policies (bound to the signed-in user: an app can only ask about itself) ═══
-- Every function an RLS policy calls must be executable by apps, so these take the subject from auth.uid(), not from an argument.
create or replace function public.money_ready_me()
returns boolean language sql stable security definer set search_path = public
as $$ select public.money_ready(auth.uid()) $$;

create or replace function public.money_blocked_with_me(p_other uuid)
returns boolean language sql stable security definer set search_path = public
as $$
  select p_other is not null and exists (
    select 1 from public.user_blocks b
    where (b.blocker_id = auth.uid() and b.blocked_id = p_other) or (b.blocker_id = p_other and b.blocked_id = auth.uid()))
$$;

create or replace function public.money_is_creator_me(p_campaign uuid)
returns boolean language sql stable security definer set search_path = public
as $$ select exists (select 1 from public.campaigns c where c.id = p_campaign and c.creator_id = auth.uid()) $$;

create or replace function public.money_is_member_me(p_campaign uuid)
returns boolean language sql stable security definer set search_path = public
as $$ select exists (select 1 from public.campaign_members m where m.campaign_id = p_campaign and m.clipper_id = auth.uid()) $$;

-- Browse: open, before its deadline, the creator still allowed (adult, not banned, not sanctioned), and no block between us
create or replace function public.money_campaign_listable_me(p_campaign uuid)
returns boolean language sql stable security definer set search_path = public
as $$
  select public.money_ready(auth.uid()) and exists (
    select 1 from public.campaigns c
    where c.id = p_campaign and c.status = 'open' and c.deadline > now()
      and public.money_is_adult(c.creator_id)
      and not exists (select 1 from public.profiles p where p.id = c.creator_id and p.money_banned)
      and not exists (select 1 from public.account_sanction_of(c.creator_id))
      and not public.money_blocked_with_me(c.creator_id))
$$;

-- the creator's or the clipper's side of a submission, for the signed-in user (the other side is hidden when they blocked me / I blocked them)
create or replace function public.money_submission_visible_me(p_submission uuid)
returns boolean language sql stable security definer set search_path = public
as $$
  select public.money_ready(auth.uid()) and exists (
    select 1 from public.campaign_submissions s join public.campaigns c on c.id = s.campaign_id
    where s.id = p_submission
      and (s.clipper_id = auth.uid() or (c.creator_id = auth.uid() and not public.money_blocked_with_me(s.clipper_id))))
$$;

create or replace function public.money_admin_me()
returns boolean language sql stable security definer set search_path = public
as $$ select public.mod_is_admin() $$;

revoke all on function public.money_ready_me(), public.money_blocked_with_me(uuid), public.money_is_creator_me(uuid), public.money_is_member_me(uuid),
  public.money_campaign_listable_me(uuid), public.money_submission_visible_me(uuid), public.money_admin_me() from public, anon;
grant execute on function public.money_ready_me(), public.money_blocked_with_me(uuid), public.money_is_creator_me(uuid), public.money_is_member_me(uuid),
  public.money_campaign_listable_me(uuid), public.money_submission_visible_me(uuid), public.money_admin_me() to authenticated;

-- ══ 8. row level security: read-only for apps ════════════════════════════════════════════════
alter table public.campaigns            enable row level security;
alter table public.campaign_members     enable row level security;
alter table public.campaign_submissions enable row level security;
alter table public.submission_links     enable row level security;
alter table public.submission_disputes  enable row level security;
alter table public.payment_cases        enable row level security;
alter table public.money_reviews        enable row level security;
alter table public.money_strikes        enable row level security;

revoke all on table public.campaigns, public.campaign_members, public.campaign_submissions, public.submission_links,
  public.submission_disputes, public.payment_cases, public.money_reviews, public.money_strikes from anon, authenticated;

-- campaigns: every column except payment_handle (members read it through campaign_payment_info)
grant select (id, creator_id, title, description, footage_url, rate_per_1k, cap_per_clip, total_budget, guaranteed_per_clip, platforms,
  view_window_days, min_views, payment_method, deadline, max_clips_per_clipper, status, paused_reason, closed_reason, terms_frozen_at,
  budget_committed, budget_left, agreement_version, creator_agreed_at, created_at) on public.campaigns to authenticated;
grant select (full_video_url, closed_at) on public.campaigns to authenticated;
grant select on public.campaign_members, public.campaign_submissions, public.submission_links, public.submission_disputes,
  public.payment_cases, public.money_reviews, public.money_strikes to authenticated;

drop policy if exists campaigns_read on public.campaigns;
create policy campaigns_read on public.campaigns for select to authenticated using (
  public.money_admin_me()
  or (public.money_ready_me() and (creator_id = auth.uid() or public.money_is_member_me(id) or public.money_campaign_listable_me(id))));

drop policy if exists members_read on public.campaign_members;
create policy members_read on public.campaign_members for select to authenticated using (
  public.money_admin_me()
  or (public.money_ready_me() and (clipper_id = auth.uid() or (public.money_is_creator_me(campaign_id) and not public.money_blocked_with_me(clipper_id)))));

drop policy if exists submissions_read on public.campaign_submissions;
create policy submissions_read on public.campaign_submissions for select to authenticated using (
  public.money_admin_me() or public.money_submission_visible_me(id));

drop policy if exists links_read on public.submission_links;
create policy links_read on public.submission_links for select to authenticated using (
  public.money_admin_me() or public.money_submission_visible_me(submission_id));

drop policy if exists disputes_read on public.submission_disputes;
create policy disputes_read on public.submission_disputes for select to authenticated using (
  public.money_admin_me() or public.money_submission_visible_me(submission_id));

drop policy if exists payment_cases_read on public.payment_cases;
create policy payment_cases_read on public.payment_cases for select to authenticated using (
  public.money_admin_me() or public.money_submission_visible_me(submission_id));

-- reviews: published ones to any ready adult (not between blocked people); an unpublished one only to its writer, so reviews stay blind
drop policy if exists reviews_read on public.money_reviews;
create policy reviews_read on public.money_reviews for select to authenticated using (
  public.money_admin_me()
  or (public.money_ready_me() and (reviewer_id = auth.uid()
      or (published_at is not null and not public.money_blocked_with_me(reviewer_id) and not public.money_blocked_with_me(reviewee_id)))));

drop policy if exists strikes_read on public.money_strikes;
create policy strikes_read on public.money_strikes for select to authenticated using (
  public.money_admin_me() or (public.money_ready_me() and user_id = auth.uid()));

-- ══ 9. members: who may join, and the first join freezes the terms ═══════════════════════════
create or replace function public.money_member_guard()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare c public.campaigns;
begin
  select * into c from public.campaigns where id = new.campaign_id for update;
  if not found then raise exception 'unknown campaign' using errcode = 'P0002'; end if;
  if new.clipper_id = c.creator_id then raise exception 'you cannot join your own campaign' using errcode = '42501'; end if;
  if auth.uid() is not null then
    if not public.money_ready(new.clipper_id) then raise exception 'Money is not available for this account' using errcode = '42501'; end if;
    if public.money_role_of(new.clipper_id) not in ('clipper', 'both') then raise exception 'pick the clipper role to join campaigns' using errcode = '42501'; end if;
  end if;
  if exists (select 1 from public.user_blocks b where (b.blocker_id = c.creator_id and b.blocked_id = new.clipper_id)
                                                   or (b.blocker_id = new.clipper_id and b.blocked_id = c.creator_id)) then
    raise exception 'you cannot join this campaign' using errcode = '42501';
  end if;
  if c.status <> 'open' or c.deadline <= now() or c.budget_committed >= c.total_budget then
    raise exception 'this campaign is not open' using errcode = '42501';
  end if;
  if not public.money_is_adult(c.creator_id)
     or exists (select 1 from public.profiles p where p.id = c.creator_id and p.money_banned) then
    raise exception 'this campaign is not open' using errcode = '42501';
  end if;
  return new;
end;
$$;
drop trigger if exists money_member_guard on public.campaign_members;
create trigger money_member_guard before insert on public.campaign_members
  for each row execute function public.money_member_guard();

create or replace function public.money_member_freeze()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  update public.campaigns set terms_frozen_at = now() where id = new.campaign_id and terms_frozen_at is null;
  return new;
end;
$$;
drop trigger if exists money_member_freeze on public.campaign_members;
create trigger money_member_freeze after insert on public.campaign_members
  for each row execute function public.money_member_freeze();

-- ══ 10. submissions: what makes one allowed, the owed amount, the budget ═════════════════════
-- owed = guaranteed + (views >= min_views ? min(views / 1000 * rate, cap) : 0), rounded to cents. proof_waived (proof was 3 days late)
-- earns the guaranteed amount only. null until the views are known.
create or replace function public.money_compute_owed(p_campaign uuid, p_views integer, p_waived boolean)
returns numeric
language sql
stable
security definer
set search_path = public
as $$
  select case
    when p_waived then round(c.guaranteed_per_clip, 2)
    when p_views is null then null
    else round(c.guaranteed_per_clip + case when p_views >= c.min_views then least((p_views::numeric / 1000) * c.rate_per_1k, c.cap_per_clip) else 0 end, 2)
  end
  from public.campaigns c where c.id = p_campaign
$$;

-- One check, used by the posts trigger (so a bad post is refused before it exists) and the submissions trigger (so no other path gets in):
-- a member, an open campaign before its deadline with budget left, and the clipper under max_clips_per_clipper. Submissions count from the
-- moment the post is created, queued or not. Serialised per campaign + clipper so two quick posts cannot both squeeze under the limit.
create or replace function public.money_check_can_submit(p_campaign uuid, p_clipper uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  c public.campaigns;
  n integer;
begin
  perform pg_advisory_xact_lock(hashtextextended('money_submit:' || p_campaign::text || ':' || p_clipper::text, 0));
  select * into c from public.campaigns where id = p_campaign;
  if not found then raise exception 'unknown campaign' using errcode = 'P0002'; end if;
  if not exists (select 1 from public.campaign_members m where m.campaign_id = p_campaign and m.clipper_id = p_clipper) then
    raise exception 'join the campaign before submitting a clip' using errcode = '42501';
  end if;
  if not public.money_ready(p_clipper) then raise exception 'Money is not available for this account' using errcode = '42501'; end if;
  if c.status <> 'open' or c.deadline <= now() or c.budget_committed >= c.total_budget then
    raise exception 'this campaign is not accepting clips' using errcode = '42501';
  end if;
  select count(*) into n from public.campaign_submissions where campaign_id = p_campaign and clipper_id = p_clipper;
  if n >= c.max_clips_per_clipper then raise exception 'you have reached the clip limit for this campaign' using errcode = '42501'; end if;
end;
$$;

create or replace function public.money_submission_guard()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  perform public.money_check_can_submit(new.campaign_id, new.clipper_id);
  return new;
end;
$$;
drop trigger if exists money_submission_guard on public.campaign_submissions;
create trigger money_submission_guard before insert on public.campaign_submissions
  for each row execute function public.money_submission_guard();

-- amount_owed is always recomputed: whatever a caller writes into it is replaced. Once a clip is approved its amount is capped at the budget
-- that is left (total - the other approved clips), so approvals can never promise more than the creator set aside; an amount that was already
-- settled does not move again unless the views are corrected. (A pending clip shows the uncapped figure.)
create or replace function public.money_submission_calc()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  raw numeric := public.money_compute_owed(new.campaign_id, new.views_claimed, new.proof_waived);
  c public.campaigns;
  others numeric;
begin
  new.amount_owed := raw;
  if raw is null or new.status not in ('approved', 'paid', 'unpaid') then return new; end if;
  select * into c from public.campaigns where id = new.campaign_id for update;
  if tg_op = 'UPDATE' and old.status in ('approved', 'paid', 'unpaid') and old.amount_owed is not null
     and new.views_claimed is not distinct from old.views_claimed and new.proof_waived is not distinct from old.proof_waived then
    new.amount_owed := old.amount_owed;
    return new;
  end if;
  select coalesce(sum(s.amount_owed), 0) into others from public.campaign_submissions s
   where s.campaign_id = new.campaign_id and s.status in ('approved', 'paid', 'unpaid') and s.id <> new.id;
  new.amount_owed := least(raw, greatest(c.total_budget - others, 0));
  return new;
end;
$$;
drop trigger if exists money_submission_calc on public.campaign_submissions;
create trigger money_submission_calc before insert or update on public.campaign_submissions
  for each row execute function public.money_submission_calc();

-- budget_committed = the owed amounts of approved clips (approved, paid, unpaid). A full budget closes the campaign to new clips.
create or replace function public.money_budget_sync()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  cid uuid := coalesce(new.campaign_id, old.campaign_id);
  total numeric;
begin
  select coalesce(sum(amount_owed), 0) into total from public.campaign_submissions
   where campaign_id = cid and status in ('approved', 'paid', 'unpaid');
  update public.campaigns
     set budget_committed = total,
         status = case when total >= total_budget and status = 'open' then 'closed' else status end,
         closed_reason = case when total >= total_budget and status = 'open' then 'budget' else closed_reason end
   where id = cid and (budget_committed is distinct from total or (total >= total_budget and status = 'open'));
  return null;
end;
$$;
drop trigger if exists money_budget_sync on public.campaign_submissions;
create trigger money_budget_sync after insert or update or delete on public.campaign_submissions
  for each row execute function public.money_budget_sync();

-- ══ 11. posts: a clip posted for a campaign becomes a submission ═════════════════════════════
-- BEFORE INSERT: the server decides clipped_for_user_id (never the client) and edited_in_tryal (false until step 3 adds the editor-session
-- proof), and refuses the post when the clipper could not submit. A campaign post is a root post (never a reaction).
create or replace function public.money_post_guard()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare creator uuid;
begin
  if new.campaign_id is null then
    new.clipped_for_user_id := null;
    new.edited_in_tryal := false;
    return new;
  end if;
  if new.parent_post_id is not null then raise exception 'a reaction cannot be a campaign clip' using errcode = '22023'; end if;
  select c.creator_id into creator from public.campaigns c where c.id = new.campaign_id;
  if creator is null then raise exception 'unknown campaign' using errcode = 'P0002'; end if;
  perform public.money_check_can_submit(new.campaign_id, new.user_id);
  new.clipped_for_user_id := creator;
  new.edited_in_tryal := false;
  return new;
end;
$$;
drop trigger if exists zzzz_money_post_guard on public.posts;
create trigger zzzz_money_post_guard before insert on public.posts
  for each row execute function public.money_post_guard();

-- AFTER INSERT: the submission, status 'posted' (the post may still be queued behind the creator's two live posts: it counts anyway)
create or replace function public.money_post_submission()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.campaign_id is null then return new; end if;
  insert into public.campaign_submissions (campaign_id, clipper_id, post_id, post_outcome)
  values (new.campaign_id, new.user_id, new.id, case when new.status = 'queued' then 'queued' else 'testing' end);
  return new;
end;
$$;
drop trigger if exists zzzz_money_post_submission on public.posts;
create trigger zzzz_money_post_submission after insert on public.posts
  for each row execute function public.money_post_submission();

-- the submission follows the post: queued -> testing -> survived / unjudged; a failed post is deleted (outcome 'failed'); anything else
-- that removes it is 'removed'. The submission itself stays and keeps counting toward the clip limit.
create or replace function public.money_post_outcome()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  update public.campaign_submissions
     set post_outcome = case new.status when 'queued' then 'queued' when 'trial' then 'testing' when 'survived' then 'survived'
                                        when 'unjudged' then 'unjudged' else 'ended' end
   where post_id = new.id;
  return null;
end;
$$;
drop trigger if exists money_post_outcome on public.posts;
create trigger money_post_outcome after update of status on public.posts
  for each row when (new.campaign_id is not null and new.status is distinct from old.status)
  execute function public.money_post_outcome();

create or replace function public.money_post_deleted()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  update public.campaign_submissions
     set post_outcome = case when exists (select 1 from public.trial_post_state s where s.post_id = old.id and s.decision = 'failed') then 'failed' else 'removed' end
   where post_id = old.id;
  return old;
end;
$$;
drop trigger if exists money_post_deleted on public.posts;
create trigger money_post_deleted before delete on public.posts
  for each row when (old.campaign_id is not null)
  execute function public.money_post_deleted();

-- ══ 12. text on Money objects goes through the same word filter as posts ═════════════════════
create or replace function public.money_text_filter()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if tg_table_name = 'submission_disputes' then
    perform public.text_check(new.note);
  elsif tg_table_name = 'payment_cases' then
    perform public.text_check(new.clipper_note); perform public.text_check(new.creator_note); perform public.text_check(new.clipper_response);
  elsif tg_table_name = 'money_reviews' then
    perform public.text_check(new.comment);
  end if;
  return new;
end;
$$;
drop trigger if exists money_text_filter on public.submission_disputes;
create trigger money_text_filter before insert or update on public.submission_disputes for each row execute function public.money_text_filter();
drop trigger if exists money_text_filter on public.payment_cases;
create trigger money_text_filter before insert or update on public.payment_cases for each row execute function public.money_text_filter();
drop trigger if exists money_text_filter on public.money_reviews;
create trigger money_text_filter before insert or update on public.money_reviews for each row execute function public.money_text_filter();

-- ══ 13. reviews: who may write one, and they never change ════════════════════════════════════
create or replace function public.money_review_guard()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  s public.campaign_submissions;
  creator uuid;
begin
  if tg_op = 'UPDATE' then
    -- immutable; only the publishing job (no signed-in user) or an admin may set published_at
    if (new.submission_id, new.reviewer_id, new.reviewee_id, new.role, new.stars, new.tags, new.comment)
       is distinct from (old.submission_id, old.reviewer_id, old.reviewee_id, old.role, old.stars, old.tags, old.comment) then
      raise exception 'reviews cannot be edited' using errcode = '42501';
    end if;
    if new.published_at is distinct from old.published_at and auth.uid() is not null and not public.mod_is_admin() then
      raise exception 'not allowed' using errcode = '42501';
    end if;
    return new;
  end if;
  select * into s from public.campaign_submissions where id = new.submission_id;
  select creator_id into creator from public.campaigns where id = s.campaign_id;
  if new.role = 'creator' and not (new.reviewer_id = creator and new.reviewee_id = s.clipper_id) then
    raise exception 'a creator review is about the clipper' using errcode = '22023';
  end if;
  if new.role = 'clipper' and not (new.reviewer_id = s.clipper_id and new.reviewee_id = creator) then
    raise exception 'a clipper review is about the creator' using errcode = '22023';
  end if;
  if not (s.status = 'paid' or (s.status in ('unpaid', 'rejected') and s.admin_resolved_at is not null)) then
    raise exception 'reviews unlock once the clip is paid or an admin has settled it' using errcode = '42501';
  end if;
  new.published_at := null;     -- always blind at first
  return new;
end;
$$;
drop trigger if exists money_review_guard on public.money_reviews;
create trigger money_review_guard before insert or update on public.money_reviews
  for each row execute function public.money_review_guard();

-- ══ 14. reports: Money objects use the existing reports table ════════════════════════════════
do $$
declare c record;
begin
  if to_regclass('public.reports') is not null then
    for c in select conname from pg_constraint
             where conrelid = 'public.reports'::regclass and contype = 'c' and pg_get_constraintdef(oid) like '%target_type%'
    loop
      execute format('alter table public.reports drop constraint %I', c.conname);
    end loop;
    alter table public.reports add constraint reports_target_type_check
      check (target_type in ('post', 'reaction', 'message', 'campaign', 'submission', 'money_review', 'money_user'));
  end if;
end $$;

-- a Money report needs a Money-ready reporter who can see the target, never under-18s
create or replace function public.money_report_guard()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare ok boolean := false;
begin
  if new.target_type not in ('campaign', 'submission', 'money_review', 'money_user') then return new; end if;
  if not public.money_ready(new.reporter_id) then raise exception 'Money is not available for this account' using errcode = '42501'; end if;
  if new.target_type = 'campaign' then
    ok := exists (select 1 from public.campaigns c where c.id = new.target_id and c.creator_id <> new.reporter_id
                  and not exists (select 1 from public.user_blocks b where (b.blocker_id = c.creator_id and b.blocked_id = new.reporter_id)));
  elsif new.target_type = 'submission' then
    ok := exists (select 1 from public.campaign_submissions s join public.campaigns c on c.id = s.campaign_id
                  where s.id = new.target_id and (c.creator_id = new.reporter_id or s.clipper_id = new.reporter_id) and s.clipper_id <> c.creator_id);
  elsif new.target_type = 'money_review' then
    ok := exists (select 1 from public.money_reviews r where r.id = new.target_id and r.published_at is not null and r.reviewer_id <> new.reporter_id);
  else
    ok := exists (select 1 from public.profiles p where p.id = new.target_id) and new.target_id <> new.reporter_id;
  end if;
  if not ok then raise exception 'you cannot report this' using errcode = '42501'; end if;
  return new;
end;
$$;
drop trigger if exists money_report_guard on public.reports;
create trigger money_report_guard before insert on public.reports
  for each row execute function public.money_report_guard();

-- ══ 15. the client-facing functions (writes go through these) ═══════════════════════════════
create or replace function public.money_require_ready(p_role text)
returns uuid
language plpgsql
stable
security definer
set search_path = public
as $$
declare me uuid := auth.uid();
begin
  if me is null then raise exception 'not signed in' using errcode = '28000'; end if;
  if not public.money_ready(me) then raise exception 'Money is not available for this account' using errcode = '42501'; end if;
  if p_role = 'creator' and public.money_role_of(me) not in ('creator', 'both') then raise exception 'pick the creator role to do this' using errcode = '42501'; end if;
  if p_role = 'clipper' and public.money_role_of(me) not in ('clipper', 'both') then raise exception 'pick the clipper role to do this' using errcode = '42501'; end if;
  return me;
end;
$$;

create or replace function public.money_create_campaign(
  p_title text, p_description text, p_footage_url text, p_rate_per_1k numeric, p_cap_per_clip numeric, p_total_budget numeric,
  p_guaranteed_per_clip numeric, p_platforms text[], p_view_window_days integer, p_min_views integer, p_payment_method text,
  p_payment_handle text, p_deadline timestamptz, p_max_clips_per_clipper integer, p_agree boolean)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := public.money_require_ready('creator');
  cid uuid;
begin
  -- once footage upload exists (migration-money-footage.sql) a campaign needs uploaded footage: this older way (a Drive / Dropbox link) is closed
  if to_regprocedure('public.money_footage_register(numeric, integer, integer, bigint)') is not null then
    raise exception 'update Tryal to post a campaign: footage is uploaded now' using errcode = '0A000';
  end if;
  if p_agree is not true then raise exception 'accept the Campaign Agreement to post' using errcode = '22023'; end if;
  insert into public.campaigns (creator_id, title, description, footage_url, rate_per_1k, cap_per_clip, total_budget, guaranteed_per_clip,
                                platforms, view_window_days, min_views, payment_method, payment_handle, deadline, max_clips_per_clipper, agreement_version)
  values (me, p_title, p_description, p_footage_url, p_rate_per_1k, p_cap_per_clip, p_total_budget, coalesce(p_guaranteed_per_clip, 0),
          p_platforms, coalesce(p_view_window_days, 7), coalesce(p_min_views, 1000), p_payment_method, p_payment_handle, p_deadline,
          coalesce(p_max_clips_per_clipper, 5), (select agreement_version from public.money_config))
  returning id into cid;
  return cid;
end;
$$;

-- edit a campaign BEFORE the first clipper joins (afterwards the freeze trigger refuses)
create or replace function public.money_update_campaign(p_campaign uuid, p_changes jsonb)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := public.money_require_ready('creator');
  c public.campaigns;
  r public.campaigns;
  k text;
  allowed text[] := array['title', 'description', 'footage_url', 'rate_per_1k', 'cap_per_clip', 'total_budget', 'guaranteed_per_clip', 'platforms',
                          'view_window_days', 'min_views', 'payment_method', 'payment_handle', 'deadline', 'max_clips_per_clipper'];
begin
  select * into c from public.campaigns where id = p_campaign and creator_id = me for update;
  if not found then raise exception 'unknown campaign' using errcode = 'P0002'; end if;
  if c.terms_frozen_at is not null then raise exception 'terms are frozen once the first clipper has joined' using errcode = '42501'; end if;
  for k in select jsonb_object_keys(coalesce(p_changes, '{}'::jsonb)) loop
    if not (k = any (allowed)) then raise exception 'cannot change %', k using errcode = '22023'; end if;
  end loop;
  r := jsonb_populate_record(c, p_changes);
  update public.campaigns set
    title = r.title, description = r.description, footage_url = r.footage_url, rate_per_1k = r.rate_per_1k, cap_per_clip = r.cap_per_clip,
    total_budget = r.total_budget, guaranteed_per_clip = r.guaranteed_per_clip, platforms = r.platforms, view_window_days = r.view_window_days,
    min_views = r.min_views, payment_method = r.payment_method, payment_handle = r.payment_handle, deadline = r.deadline,
    max_clips_per_clipper = r.max_clips_per_clipper
  where id = p_campaign;
end;
$$;

-- the creator closes (or pauses / reopens) their own campaign; the system's pauses (overdue payment, banned) are not theirs to lift
create or replace function public.money_set_campaign_status(p_campaign uuid, p_status text)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := public.money_require_ready('creator');
  c public.campaigns;
begin
  if p_status not in ('open', 'paused', 'closed') then raise exception 'unknown status' using errcode = '22023'; end if;
  select * into c from public.campaigns where id = p_campaign and creator_id = me for update;
  if not found then raise exception 'unknown campaign' using errcode = 'P0002'; end if;
  if c.status = 'closed' then raise exception 'a closed campaign stays closed' using errcode = '42501'; end if;
  if c.status = 'paused' and c.paused_reason is distinct from 'creator' then raise exception 'this campaign is paused by Tryal' using errcode = '42501'; end if;
  if p_status = 'open' and (c.deadline <= now() or c.budget_committed >= c.total_budget) then raise exception 'this campaign cannot reopen' using errcode = '42501'; end if;
  update public.campaigns
     set status = p_status,
         paused_reason = case p_status when 'paused' then 'creator' else null end,
         closed_reason = case p_status when 'closed' then 'creator' else closed_reason end
   where id = p_campaign;
end;
$$;

-- more budget after the freeze (never less). A campaign that closed because the budget ran out reopens if its deadline has not passed.
create or replace function public.money_increase_budget(p_campaign uuid, p_new_total numeric)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := public.money_require_ready('creator');
  c public.campaigns;
begin
  select * into c from public.campaigns where id = p_campaign and creator_id = me for update;
  if not found then raise exception 'unknown campaign' using errcode = 'P0002'; end if;
  if p_new_total is null or p_new_total <= c.total_budget then raise exception 'the new budget must be higher than the current one' using errcode = '22023'; end if;
  if p_new_total > 10000000 then raise exception 'that budget is too high' using errcode = '22023'; end if;
  perform set_config('tryal.budget_increase', '1', true);
  update public.campaigns
     set total_budget = round(p_new_total, 2),
         status = case when status = 'closed' and closed_reason = 'budget' and deadline > now() then 'open' else status end,
         closed_reason = case when status = 'closed' and closed_reason = 'budget' and deadline > now() then null else closed_reason end
   where id = p_campaign;
  perform set_config('tryal.budget_increase', '', true);
end;
$$;

-- join: the terms the clipper saw are stored with the membership; the first join freezes them (trigger). Joining also opens (or reuses) the
-- message thread with the creator and puts one message in it that summarizes the terms (sent as the clipper; it goes through the same word
-- filter and checks as any message, and if that fails for any reason the join still succeeds, just without the message).
create or replace function public.money_join_campaign(p_campaign uuid, p_agree boolean)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := public.money_require_ready('clipper');
  c public.campaigns;
  cid uuid;
  body text;
begin
  if p_agree is not true then raise exception 'accept the Clipper Agreement to join' using errcode = '22023'; end if;
  select * into c from public.campaigns where id = p_campaign;
  if not found or not public.money_campaign_listable_me(p_campaign) then raise exception 'this campaign is not open' using errcode = '42501'; end if;
  insert into public.campaign_members (campaign_id, clipper_id, agreed_terms)
  values (p_campaign, me, jsonb_build_object(
    'rate_per_1k', c.rate_per_1k, 'cap_per_clip', c.cap_per_clip, 'guaranteed_per_clip', c.guaranteed_per_clip, 'total_budget', c.total_budget,
    'min_views', c.min_views, 'view_window_days', c.view_window_days, 'platforms', c.platforms, 'deadline', c.deadline,
    'max_clips_per_clipper', c.max_clips_per_clipper, 'payment_method', c.payment_method, 'footage_url', c.footage_url,
    'clipper_agreement_version', (select agreement_version from public.money_config), 'agreed_at', now()))
  on conflict do nothing;
  if found then
    begin
      body := format('I joined your campaign "%s". Terms: $%s per 1,000 views (from %s views), up to $%s per clip%s, budget $%s, up to %s clips each, post on %s, view window %s days, closes %s. Let''s use this thread for questions about the work.',
                     c.title, to_char(c.rate_per_1k, 'FM999999990.00'), c.min_views, to_char(c.cap_per_clip, 'FM999999990.00'),
                     case when c.guaranteed_per_clip > 0 then format(', plus $%s guaranteed per approved clip', to_char(c.guaranteed_per_clip, 'FM999999990.00')) else '' end,
                     to_char(c.total_budget, 'FM999999990.00'), c.max_clips_per_clipper, array_to_string(c.platforms, ', '), c.view_window_days,
                     to_char(c.deadline at time zone 'UTC', 'Mon DD YYYY'));
      cid := public.chat_conversation_for(c.creator_id);
      insert into public.chat_messages (conversation_id, sender_id, body) values (cid, me, left(body, 2000));
      update public.chat_conversations set last_message_at = now() where id = cid;
      perform public.friends_notify(c.creator_id, me, 'message');
    exception when others then
      raise notice 'money_join_campaign: joined, but the terms message was not sent (%)', sqlerrm;
    end;
  end if;
end;
$$;

-- the creator's payment handle (plain text, shown to members and the creator only)
create or replace function public.campaign_payment_info(p_campaign uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  c public.campaigns;
begin
  if me is null or not public.money_ready(me) then raise exception 'Money is not available for this account' using errcode = '42501'; end if;
  select * into c from public.campaigns where id = p_campaign;
  if not found or not (c.creator_id = me or public.money_is_member_me(p_campaign)) then raise exception 'not allowed' using errcode = '42501'; end if;
  return jsonb_build_object('payment_method', c.payment_method, 'payment_handle', c.payment_handle);
end;
$$;

-- the owner bans / unbans an account's Money access (the review queue screen comes in a later step); logged like every moderation action
create or replace function public.admin_money_set_banned(p_user uuid, p_banned boolean, p_reason text default null)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if not public.mod_is_admin() then raise exception 'not allowed' using errcode = '42501'; end if;
  update public.profiles set money_banned = coalesce(p_banned, false) where id = p_user;
  if not found then raise exception 'unknown user' using errcode = 'P0002'; end if;
  if p_banned then
    update public.campaigns set status = 'paused', paused_reason = 'creator_banned' where creator_id = p_user and status = 'open';
  end if;
  insert into public.moderation_log (actor, action, target_user, detail)
  values (auth.uid(), case when p_banned then 'money_ban' else 'money_unban' end, p_user, jsonb_build_object('reason', p_reason));
end;
$$;

-- who is banned from Money (the column itself is not readable by apps): admins only
create or replace function public.admin_money_banned_users()
returns table (user_id uuid, username text)
language plpgsql
stable
security definer
set search_path = public
as $$
begin
  if not public.mod_is_admin() then raise exception 'not allowed' using errcode = '42501'; end if;
  return query select p.id, p.username::text from public.profiles p where p.money_banned order by p.username;
end;
$$;

-- reputation: published reviews only, plus the creator's payment record (paid / approved, average days to pay, late count)
create or replace function public.money_profile_stats(p_user uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  stars numeric;
  n integer;
  approved integer;
  paid integer;
  days numeric;
  late integer;
begin
  if me is null or not public.money_ready(me) then raise exception 'Money is not available for this account' using errcode = '42501'; end if;
  if p_user is null or not public.money_is_adult(p_user) then return null; end if;
  select round(avg(r.stars)::numeric, 1), count(*) into stars, n from public.money_reviews r where r.reviewee_id = p_user and r.published_at is not null;
  select count(*) filter (where s.status in ('approved', 'paid', 'unpaid')),
         count(*) filter (where s.status = 'paid'),
         round((avg(extract(epoch from (coalesce(s.paid_marked_at, s.received_at) - s.approved_at)) / 86400)
               filter (where s.status = 'paid' and s.approved_at is not null and coalesce(s.paid_marked_at, s.received_at) is not null))::numeric, 1)
    into approved, paid, days
    from public.campaign_submissions s join public.campaigns c on c.id = s.campaign_id where c.creator_id = p_user;
  select count(*) into late from public.money_strikes where user_id = p_user and kind = 'late_payment';
  return jsonb_build_object('rating_avg', stars, 'rating_count', n, 'approved_count', approved, 'paid_count', paid, 'avg_days_to_pay', days, 'late_count', late);
end;
$$;

revoke all on function public.money_complete_onboarding(text, text[]), public.my_money_profile(), public.money_create_campaign(text, text, text, numeric, numeric, numeric, numeric, text[], integer, integer, text, text, timestamptz, integer, boolean),
  public.money_update_campaign(uuid, jsonb), public.money_set_campaign_status(uuid, text), public.money_join_campaign(uuid, boolean),
  public.money_increase_budget(uuid, numeric), public.admin_money_banned_users(),
  public.campaign_payment_info(uuid), public.money_profile_stats(uuid), public.admin_money_set_banned(uuid, boolean, text) from public, anon;
grant execute on function public.money_complete_onboarding(text, text[]), public.my_money_profile(), public.money_create_campaign(text, text, text, numeric, numeric, numeric, numeric, text[], integer, integer, text, text, timestamptz, integer, boolean),
  public.money_update_campaign(uuid, jsonb), public.money_set_campaign_status(uuid, text), public.money_join_campaign(uuid, boolean),
  public.money_increase_budget(uuid, numeric), public.admin_money_banned_users(),
  public.campaign_payment_info(uuid), public.money_profile_stats(uuid), public.admin_money_set_banned(uuid, boolean, text) to authenticated;
revoke all on function public.my_features() from public, anon;
grant execute on function public.my_features() to authenticated;

-- internals: not callable by apps
revoke all on function public.money_allowed(uuid), public.money_ready(uuid), public.money_role_of(uuid), public.money_required_rules(text),
  public.money_url_host(text), public.money_is_footage_host(text), public.money_handle_ok(text), public.money_compute_owed(uuid, integer, boolean),
  public.money_check_can_submit(uuid, uuid), public.money_require_ready(text), public.campaigns_validate(), public.campaigns_freeze_guard(),
  public.money_member_guard(), public.money_member_freeze(), public.money_submission_guard(), public.money_submission_calc(), public.money_budget_sync(),
  public.money_post_guard(), public.money_post_submission(), public.money_post_outcome(), public.money_post_deleted(), public.money_text_filter(),
  public.money_review_guard(), public.money_report_guard(), public.money_strike_apply(), public.profiles_money_banned_guard() from public, anon, authenticated;

-- ══ 16. the private bucket for view proof and payment receipts ═══════════════════════════════
-- Path: <submission id>/proof/<file> (the clipper, 1-3 screenshots) or <submission id>/receipt/<file> (the creator). Readable by the clipper,
-- the creator and admins. Apps can add files but never change or delete them (evidence). Images only, small.
create or replace function public.money_proof_access(p_name text, p_write boolean)
returns boolean
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  sid uuid;
  kind text := split_part(p_name, '/', 2);
  s public.campaign_submissions;
  creator uuid;
begin
  if me is null then return false; end if;
  begin sid := split_part(p_name, '/', 1)::uuid; exception when others then return false; end;
  if not p_write and public.mod_is_admin() then return true; end if;
  if not public.money_ready(me) then return false; end if;
  select * into s from public.campaign_submissions where id = sid;
  if not found then return false; end if;
  select creator_id into creator from public.campaigns where id = s.campaign_id;
  if p_write then
    return (kind = 'proof' and s.clipper_id = me) or (kind = 'receipt' and creator = me);
  end if;
  return s.clipper_id = me or (creator = me and not public.money_blocked_with_me(s.clipper_id));
end;
$$;
revoke all on function public.money_proof_access(text, boolean) from public, anon;
grant execute on function public.money_proof_access(text, boolean) to authenticated;

do $$
begin
  if to_regclass('storage.objects') is not null and to_regclass('storage.buckets') is not null then
    insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
    values ('money-proof', 'money-proof', false, 8388608, array['image/jpeg', 'image/png', 'image/webp', 'image/heic'])
    on conflict (id) do update set public = false, file_size_limit = 8388608, allowed_mime_types = array['image/jpeg', 'image/png', 'image/webp', 'image/heic'];
    drop policy if exists "money proof read" on storage.objects;
    create policy "money proof read" on storage.objects for select to authenticated
      using (bucket_id = 'money-proof' and public.money_proof_access(name, false));
    drop policy if exists "money proof add" on storage.objects;
    create policy "money proof add" on storage.objects for insert to authenticated
      with check (bucket_id = 'money-proof' and public.money_proof_access(name, true));
  end if;
end $$;

-- ══ 17. messaging about a campaign ═══════════════════════════════════════════════════════════
-- Messaging is open between adults (migration-tryal-friends.sql). On top of that, a creator and a clipper who has joined their campaign can
-- always message each other about it, whatever either has chosen in "Who can message me" (friends / friends 7 days / nobody) and without being
-- friends. Unchanged: a block in either direction ends it, an under-18 account is never part of it, the word filter, the one-sided-message
-- limit and sanctions. It exists only while the membership does.
create or replace function public.money_chat_pair(p_a uuid, p_b uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select p_a is not null and p_b is not null and p_a <> p_b
     and exists (select 1 from public.campaign_members m join public.campaigns c on c.id = m.campaign_id
                  where (c.creator_id = p_a and m.clipper_id = p_b) or (c.creator_id = p_b and m.clipper_id = p_a))
     and public.money_is_adult(p_a) and public.money_is_adult(p_b)
     and not exists (select 1 from public.profiles p where p.id in (p_a, p_b) and p.money_banned)
     and not public.friends_blocked(p_a, p_b)
$$;

-- Copies of the two functions migration-tryal-friends.sql defines, with the lines marked "-- MONEY" added (scripts/test-migration-order.mjs
-- checks that everything else is identical to that file's version, so the two cannot drift apart).
create or replace function public.chat_check_stranger(p_from uuid, p_to uuid)
returns void
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  pol text;
begin
  if public.friends_is_minor(p_from) or public.friends_is_minor(p_to) then
    raise exception 'you cannot message this person' using errcode = '42501';
  end if;
  if public.money_chat_pair(p_from, p_to) then return; end if;   -- MONEY
  select dm_policy into pol from public.creator_controls where user_id = p_to;
  if coalesce(pol, 'everyone') <> 'everyone' then
    raise exception 'This person is not taking messages from people who are not their friends.' using errcode = '42501';
  end if;
end;
$$;

create or replace function public.chat_messages_guard()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  c public.chat_conversations;
  other uuid;
  cfg public.harassment_config;
  pol text;
  since timestamptz;
begin
  select * into c from public.chat_conversations where id = new.conversation_id;
  if not found then return new; end if;
  other := case when c.user_a = new.sender_id then c.user_b else c.user_a end;
  select * into cfg from public.harassment_config where id;
  -- 1. the words
  perform public.text_check(new.body);
  -- 2. who may message the recipient (people who are not friends: adults only, and only when the recipient takes messages from
  --    everyone; migration-tryal-friends.sql)
  if not public.friends_are(new.sender_id, other) then
    perform public.chat_check_stranger(new.sender_id, other);
  end if;
  select dm_policy into pol from public.creator_controls where user_id = other;
  if public.money_chat_pair(new.sender_id, other) then pol := null; end if;   -- MONEY
  if pol = 'nobody' then
    raise exception 'This person is not taking messages right now.' using errcode = '42501';
  elsif pol = 'friends_7d' then
    select created_at into since from public.friendships where user_a = least(new.sender_id, other) and user_b = greatest(new.sender_id, other);
    if since is null or since > now() - (cfg.friend_min_days * interval '1 day') then
      raise exception 'This person only takes messages from people who have been friends for % days.', cfg.friend_min_days using errcode = '42501';
    end if;
  end if;
  -- 3. no endless one-sided messaging
  if public.harassment_unanswered(new.conversation_id, new.sender_id) >= cfg.unanswered_limit then
    raise exception 'Wait for a reply before sending more.' using errcode = '42501';
  end if;
  return new;
end;
$$;
revoke all on function public.money_chat_pair(uuid, uuid), public.chat_check_stranger(uuid, uuid), public.chat_messages_guard() from public, anon, authenticated;

-- ══ 18. the old dashboard feed function get_feed no longer reads birthdate as the caller ═════
-- get_feed (made in the dashboard, saved in supabase/get_feed.sql) is not security definer and reads profiles.birthdate. Nobody can run it
-- any more (migration-stranger-only.sql revoked execute from apps, because it is not stranger-aware: that stays), but if it were ever run as
-- a signed-in user the birthdate lock-down would make it fail. So its one birthdate lookup becomes a call to my_hides_mature(), which answers
-- ONLY about the caller (security definer; it reveals nothing about anybody else). Only that statement is replaced, in the live function's own
-- text (whitespace and Windows line endings tolerated), and its privileges are left exactly as they are. If the live function is not the
-- version in the repo (the statement is not found) it is left alone and a notice says so.
create or replace function public.my_hides_mature()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select coalesce((select public.age_tier(p.birthdate) in ('under_13', 'teen') from public.profiles p where p.id = auth.uid()), false)
$$;
revoke all on function public.my_hides_mature() from public, anon;
grant execute on function public.my_hides_mature() to authenticated;

do $$
declare
  f record;
  def text;
  patched text;
begin
  for f in select p.oid from pg_proc p where p.pronamespace = 'public'::regnamespace and p.proname = 'get_feed' and p.prokind = 'f' loop
    def := pg_get_functiondef(f.oid);
    patched := regexp_replace(def,
      'select\s+coalesce\(\s*public\.age_tier\(\s*pr\.birthdate\s*\)\s+in\s*\(\s*''under_13''\s*,\s*''teen''\s*\)\s*,\s*false\s*\)\s+into\s+v_hide_mature\s+from\s+public\.profiles\s+pr\s+where\s+pr\.id\s*=\s*v_uid\s*;',
      'v_hide_mature := public.my_hides_mature();', 'i');
    if patched <> def then
      execute patched;
      raise notice 'get_feed: the birthdate lookup now goes through my_hides_mature()';
    elsif def !~* 'birthdate' then
      raise notice 'get_feed: already does not read birthdate';
    else
      raise notice 'get_feed: reads birthdate but is not the version in supabase/get_feed.sql, so it was NOT changed';
    end if;
  end loop;
end $$;

-- ══ 19. profile columns: money_banned is not publicly readable ═══════════════════════════════
-- profiles is readable by everyone with a table-wide select grant. money_refresh_profile_grants() (migration-money.sql) replaces it with an
-- explicit column list that leaves out money_banned and birthdate_set_at (and birthdate once the birthdate lock-down is on). The user reads
-- their own state through my_features() / my_money_profile(), admins through admin_money_banned_users(), the money functions as the owner.
-- After ANY later migration that adds a profiles column, run: select public.money_refresh_profile_grants();
select public.money_refresh_profile_grants();

-- ══════════════════════════════════════════════════════════════════════════════
-- PART: migration-money-footage.sql
-- ══════════════════════════════════════════════════════════════════════════════
-- Tryal Money: CAMPAIGN FOOTAGE (MONEY_TAB_SPEC.md sections 3, 3.1, 4). Idempotent; applied AFTER migration-post-links.sql and migration-money-board.sql
-- (apply with: node scripts/apply-migrations.mjs --only=migration-post-links.sql,migration-money.sql,migration-money-board.sql,migration-money-footage.sql
-- on a database that has none of them, or just this file once the others are in).
--
-- Creators upload videos from their camera roll into a PRIVATE bucket (campaign-footage): up to 60 minutes in total per campaign, each video up to
-- 30 minutes. The phone compresses first and uploads in resumable chunks (TUS, straight to Storage as the signed-in creator). Nobody reads a file
-- except the creator and the clippers who joined that campaign: reading goes through Storage's signed URLs, and Storage only signs for people the
-- policy below allows (there is no public URL, no list, no policy for anyone else, and apps can never update or delete a file).
-- Footage is deleted 30 days after the campaign closes (or 30 days after its deadline), and unattached uploads after 7 days: the files go through
-- the existing delete queue (trial_media_delete_queue + the delete-media function), the rows are marked 'deleted'.

-- ══ 1. limits live in money_config ═══════════════════════════════════════════════════════════
alter table public.money_config add column if not exists max_footage_seconds_total integer not null default 3600;     -- 60 minutes per campaign
alter table public.money_config add column if not exists max_footage_seconds_each  integer not null default 1800;     -- 30 minutes per video
alter table public.money_config add column if not exists max_footage_bytes         bigint  not null default 2147483648;   -- 2 GB per video
alter table public.money_config add column if not exists footage_delete_days       integer not null default 30;
alter table public.money_config add column if not exists orphan_footage_days       integer not null default 7;
alter table public.money_config add column if not exists max_draft_footage         integer not null default 30;
-- the Campaign Agreement and the Clipper Agreement changed (uploaded footage, footage use, tracked links): everybody reads and ticks again
update public.money_config set agreement_version = greatest(agreement_version, 2);

-- ══ 2. the footage table ═════════════════════════════════════════════════════════════════════
create table if not exists public.campaign_footage (
  id               uuid primary key default gen_random_uuid(),
  creator_id       uuid not null references public.profiles(id) on delete cascade,
  campaign_id      uuid references public.campaigns(id) on delete cascade,       -- null until the campaign is created (a draft upload)
  storage_path     text not null unique,                                         -- <creator id>/<id>.mp4
  thumb_path       text not null unique,                                         -- <creator id>/<id>.jpg
  duration_seconds numeric(8,2) not null check (duration_seconds > 0),
  width            integer not null check (width > 0 and width <= 8192),
  height           integer not null check (height > 0 and height <= 8192),
  size_bytes       bigint not null check (size_bytes > 0),
  sort_order       integer not null default 0,
  status           text not null default 'uploading' check (status in ('uploading', 'ready', 'failed', 'deleted')),
  thumb_ok         boolean not null default false,
  created_at       timestamptz not null default now(),
  ready_at         timestamptz,
  deleted_at       timestamptz
);
create index if not exists campaign_footage_creator_idx on public.campaign_footage (creator_id, campaign_id);
create index if not exists campaign_footage_campaign_idx on public.campaign_footage (campaign_id) where campaign_id is not null;
alter table public.campaign_footage enable row level security;
revoke all on table public.campaign_footage from anon, authenticated;
grant select on public.campaign_footage to authenticated;
drop policy if exists footage_read on public.campaign_footage;
create policy footage_read on public.campaign_footage for select to authenticated using (
  public.money_admin_me()
  or (public.money_ready_me() and status <> 'deleted' and (
        creator_id = auth.uid()
        or (campaign_id is not null and status = 'ready' and public.money_is_member_me(campaign_id) and not public.money_blocked_with_me(creator_id)))));

-- Who may add a video, and how much: checked on every insert, whoever inserts. Serialised per creator so two quick uploads cannot both squeeze in.
create or replace function public.money_footage_guard()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  cfg public.money_config;
  c public.campaigns;
  used numeric;
  n integer;
begin
  select * into cfg from public.money_config;
  perform pg_advisory_xact_lock(hashtextextended('money_footage:' || new.creator_id::text, 0));
  if auth.uid() is not null then
    if not public.money_ready(new.creator_id) then raise exception 'Money is not available for this account' using errcode = '42501'; end if;
    if public.money_role_of(new.creator_id) not in ('creator', 'both') then raise exception 'pick the creator role to add footage' using errcode = '42501'; end if;
  end if;
  if new.duration_seconds > cfg.max_footage_seconds_each then
    raise exception 'each video can be at most % minutes', cfg.max_footage_seconds_each / 60 using errcode = '22023';
  end if;
  if new.size_bytes > cfg.max_footage_bytes then raise exception 'that video file is too large' using errcode = '22023'; end if;
  if new.campaign_id is not null then
    select * into c from public.campaigns where id = new.campaign_id;
    if not found or c.creator_id <> new.creator_id then raise exception 'unknown campaign' using errcode = 'P0002'; end if;
    if c.terms_frozen_at is not null and auth.uid() is not null then raise exception 'footage is frozen once the first clipper has joined' using errcode = '42501'; end if;
  end if;
  select coalesce(sum(duration_seconds), 0), count(*) into used, n from public.campaign_footage
   where creator_id = new.creator_id and campaign_id is not distinct from new.campaign_id and status in ('uploading', 'ready');
  if used + new.duration_seconds > cfg.max_footage_seconds_total then
    raise exception 'a campaign can have at most % minutes of footage', cfg.max_footage_seconds_total / 60 using errcode = '22023';
  end if;
  if new.campaign_id is null and n >= cfg.max_draft_footage then raise exception 'too many videos at once' using errcode = '22023'; end if;
  return new;
end;
$$;
drop trigger if exists money_footage_guard on public.campaign_footage;
create trigger money_footage_guard before insert on public.campaign_footage
  for each row execute function public.money_footage_guard();

-- once a campaign has a clipper its footage is frozen with the other terms: nobody with an account can change or remove it (the purge, which has
-- no signed-in user, can)
create or replace function public.money_footage_change_guard()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare frozen boolean;
begin
  if auth.uid() is null then return coalesce(new, old); end if;
  select (terms_frozen_at is not null) into frozen from public.campaigns where id = old.campaign_id;
  if coalesce(frozen, false) then raise exception 'footage is frozen once the first clipper has joined' using errcode = '42501'; end if;
  return coalesce(new, old);
end;
$$;
drop trigger if exists money_footage_change_guard on public.campaign_footage;
create trigger money_footage_change_guard before update or delete on public.campaign_footage
  for each row when (old.campaign_id is not null) execute function public.money_footage_change_guard();

-- ══ 3. what the app calls ════════════════════════════════════════════════════════════════════
-- Register a video before uploading it (after the phone has compressed it, so the size is the real one). Returns where to upload.
create or replace function public.money_footage_register(p_duration_seconds numeric, p_width integer, p_height integer, p_size_bytes bigint)
returns table (id uuid, storage_path text, thumb_path text)
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := public.money_require_ready('creator');
  fid uuid := gen_random_uuid();
begin
  insert into public.campaign_footage (id, creator_id, storage_path, thumb_path, duration_seconds, width, height, size_bytes)
  values (fid, me, me::text || '/' || fid::text || '.mp4', me::text || '/' || fid::text || '.jpg', round(p_duration_seconds, 2), p_width, p_height, p_size_bytes);
  return query select f.id, f.storage_path, f.thumb_path from public.campaign_footage f where f.id = fid;
end;
$$;

-- The upload finished: check the file really is in Storage at the registered size, then the video is ready (the thumbnail is a bonus).
create or replace function public.money_footage_complete(p_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := public.money_require_ready('creator');
  f public.campaign_footage;
  sz bigint;
begin
  select * into f from public.campaign_footage where id = p_id and creator_id = me for update;
  if not found then raise exception 'unknown video' using errcode = 'P0002'; end if;
  if f.status = 'ready' then return; end if;
  if f.status <> 'uploading' then raise exception 'this video cannot be completed' using errcode = '42501'; end if;
  select (o.metadata ->> 'size')::bigint into sz from storage.objects o where o.bucket_id = 'campaign-footage' and o.name = f.storage_path;
  if sz is null or sz <> f.size_bytes then raise exception 'the upload is not complete yet' using errcode = '55000'; end if;
  update public.campaign_footage
     set status = 'ready', ready_at = now(),
         thumb_ok = exists (select 1 from storage.objects o where o.bucket_id = 'campaign-footage' and o.name = f.thumb_path)
   where id = p_id;
end;
$$;

-- a failed upload the app gave up on, so its slot (minutes) is free again
create or replace function public.money_footage_fail(p_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare me uuid := public.money_require_ready('creator');
begin
  update public.campaign_footage set status = 'failed' where id = p_id and creator_id = me and status = 'uploading';
  insert into public.trial_media_delete_queue (post_id, bucket, path)
    select f.id, 'campaign-footage', p from public.campaign_footage f, unnest(array[f.storage_path, f.thumb_path]) p
     where f.id = p_id and f.creator_id = me and f.status = 'failed' on conflict do nothing;
end;
$$;

-- remove a video I added (not once the campaign has a clipper): its files are queued for deletion
create or replace function public.money_footage_remove(p_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare me uuid := public.money_require_ready('creator');
begin
  if not exists (select 1 from public.campaign_footage where id = p_id and creator_id = me and status <> 'deleted') then raise exception 'unknown video' using errcode = 'P0002'; end if;
  update public.campaign_footage set status = 'deleted', deleted_at = now() where id = p_id and creator_id = me;
  insert into public.trial_media_delete_queue (post_id, bucket, path)
    select f.id, 'campaign-footage', p from public.campaign_footage f, unnest(array[f.storage_path, f.thumb_path]) p where f.id = p_id on conflict do nothing;
end;
$$;

-- Post the campaign with its uploaded footage. Every video must be mine, ready and not yet used; the minutes were checked when each was added.
create or replace function public.money_create_campaign_with_footage(
  p_title text, p_description text, p_full_video_url text, p_rate_per_1k numeric, p_cap_per_clip numeric, p_total_budget numeric,
  p_guaranteed_per_clip numeric, p_platforms text[], p_view_window_days integer, p_min_views integer, p_payment_method text,
  p_payment_handle text, p_deadline timestamptz, p_max_clips_per_clipper integer, p_agree boolean, p_footage_ids uuid[])
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := public.money_require_ready('creator');
  cid uuid;
  want uuid[] := (select array_agg(distinct x) from unnest(coalesce(p_footage_ids, '{}')) x);
  have integer;
begin
  if p_agree is not true then raise exception 'accept the Campaign Agreement to post' using errcode = '22023'; end if;
  if want is null or cardinality(want) = 0 then raise exception 'add at least one video' using errcode = '22023'; end if;
  perform 1 from public.campaign_footage where id = any (want) and creator_id = me for update;
  select count(*) into have from public.campaign_footage where id = any (want) and creator_id = me and campaign_id is null and status = 'ready';
  if have <> cardinality(want) then raise exception 'some videos are missing or still uploading' using errcode = '55000'; end if;
  insert into public.campaigns (creator_id, title, description, full_video_url, rate_per_1k, cap_per_clip, total_budget, guaranteed_per_clip,
                                platforms, view_window_days, min_views, payment_method, payment_handle, deadline, max_clips_per_clipper, agreement_version)
  values (me, p_title, p_description, nullif(btrim(coalesce(p_full_video_url, '')), ''), p_rate_per_1k, p_cap_per_clip, p_total_budget, coalesce(p_guaranteed_per_clip, 0),
          p_platforms, coalesce(p_view_window_days, 7), coalesce(p_min_views, 1000), p_payment_method, p_payment_handle, p_deadline,
          coalesce(p_max_clips_per_clipper, 5), (select agreement_version from public.money_config))
  returning id into cid;
  update public.campaign_footage f set campaign_id = cid, sort_order = array_position(p_footage_ids, f.id) where f.id = any (want);
  return cid;
end;
$$;

-- ══ 4. who may put a file in the bucket and who may read it (Storage policies; signed URLs follow the read policy) ══
create or replace function public.money_footage_upload_ok(p_name text)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select auth.uid() is not null and public.money_ready(auth.uid())
     and exists (select 1 from public.campaign_footage f
                  where f.creator_id = auth.uid() and f.status = 'uploading' and (f.storage_path = p_name or f.thumb_path = p_name))
$$;

create or replace function public.money_footage_read_ok(p_name text)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select auth.uid() is not null and (
    public.mod_is_admin()
    or (public.money_ready(auth.uid()) and exists (
         select 1 from public.campaign_footage f
          where (f.storage_path = p_name or f.thumb_path = p_name) and f.status in ('uploading', 'ready')
            and (f.creator_id = auth.uid()
                 or (f.status = 'ready' and f.campaign_id is not null
                     and exists (select 1 from public.campaign_members m where m.campaign_id = f.campaign_id and m.clipper_id = auth.uid())
                     and not exists (select 1 from public.user_blocks b where (b.blocker_id = f.creator_id and b.blocked_id = auth.uid())
                                                                           or (b.blocker_id = auth.uid() and b.blocked_id = f.creator_id)))))))
$$;

do $$
begin
  if to_regclass('storage.objects') is not null and to_regclass('storage.buckets') is not null then
    insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
    values ('campaign-footage', 'campaign-footage', false, 2147483648, array['video/mp4', 'video/quicktime', 'image/jpeg'])
    on conflict (id) do update set public = false, file_size_limit = 2147483648, allowed_mime_types = array['video/mp4', 'video/quicktime', 'image/jpeg'];
    drop policy if exists "campaign footage read" on storage.objects;
    create policy "campaign footage read" on storage.objects for select to authenticated
      using (bucket_id = 'campaign-footage' and public.money_footage_read_ok(name));
    drop policy if exists "campaign footage add" on storage.objects;
    create policy "campaign footage add" on storage.objects for insert to authenticated
      with check (bucket_id = 'campaign-footage' and public.money_footage_upload_ok(name));
  end if;
end $$;

-- ══ 5. deletion: 30 days after the campaign closes, 7 days for an upload nobody used ═══════════════
-- Marks the rows 'deleted' and queues the files; the delete-media function removes them from Storage (it is scheduled by ship.sh).
create or replace function public.money_footage_purge()
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  cfg public.money_config;
  n integer;
begin
  select * into cfg from public.money_config;
  with gone as (
    update public.campaign_footage f set status = 'deleted', deleted_at = now()
     where f.status <> 'deleted' and (
           (f.campaign_id is null and f.created_at < now() - make_interval(days => cfg.orphan_footage_days))
        or (f.campaign_id is not null and exists (
              select 1 from public.campaigns c
               where c.id = f.campaign_id
                 and ((c.status = 'closed' and c.closed_at < now() - make_interval(days => cfg.footage_delete_days))
                      or c.deadline < now() - make_interval(days => cfg.footage_delete_days)))))
    returning f.id, f.storage_path, f.thumb_path)
  , queued as (
    insert into public.trial_media_delete_queue (post_id, bucket, path)
      select g.id, 'campaign-footage', p from gone g, unnest(array[g.storage_path, g.thumb_path]) p on conflict do nothing
      returning 1)
  select count(*) into n from gone;
  return n;
end;
$$;

do $$
begin
  if to_regnamespace('cron') is not null then
    perform cron.unschedule(j.jobid) from cron.job j where j.jobname = 'money-footage-purge';
    perform cron.schedule('money-footage-purge', '30 3 * * *', 'select public.money_footage_purge()');
  end if;
exception when others then
  raise notice 'could not schedule money-footage-purge (%): run select public.money_footage_purge() by hand now and then', sqlerrm;
end $$;

-- ══ 6. who may call what ═════════════════════════════════════════════════════════════════════
revoke all on function public.money_footage_guard(), public.money_footage_change_guard(), public.money_footage_purge() from public, anon, authenticated;
revoke all on function public.money_footage_register(numeric, integer, integer, bigint), public.money_footage_complete(uuid), public.money_footage_fail(uuid),
  public.money_footage_remove(uuid), public.money_footage_upload_ok(text), public.money_footage_read_ok(text),
  public.money_create_campaign_with_footage(text, text, text, numeric, numeric, numeric, numeric, text[], integer, integer, text, text, timestamptz, integer, boolean, uuid[])
  from public, anon;
grant execute on function public.money_footage_register(numeric, integer, integer, bigint), public.money_footage_complete(uuid), public.money_footage_fail(uuid),
  public.money_footage_remove(uuid), public.money_footage_upload_ok(text), public.money_footage_read_ok(text),
  public.money_create_campaign_with_footage(text, text, text, numeric, numeric, numeric, numeric, text[], integer, integer, text, text, timestamptz, integer, boolean, uuid[])
  to authenticated;

-- ══════════════════════════════════════════════════════════════════════════════
-- CHECKS (read-only): one table. Every row should say ok (or info). Anything else says what to do.
-- ══════════════════════════════════════════════════════════════════════════════
select src, check_name, status, detail from (
  select 'footage' as src, check_name, status, detail, 1 as o1 from (
select check_name, status, detail
from (
  select 'bucket campaign-footage exists and is private' as check_name,
         case when b.id is null then 'MISSING: run migration-money-footage.sql'
              when b.public then 'NOT PRIVATE: the bucket is public, fix it now' else 'ok' end as status,
         coalesce('limit ' || b.file_size_limit || ' bytes; types ' || array_to_string(b.allowed_mime_types, ','), '-') as detail, 1 as grp
    from (select 1) one left join storage.buckets b on b.id = 'campaign-footage'
  union all
  select 'storage policies on the bucket (read + add, nothing else)',
         case when (select count(*) from pg_policies where schemaname = 'storage' and tablename = 'objects' and policyname in ('campaign footage read', 'campaign footage add')) = 2 then 'ok' else 'MISSING: run migration-money-footage.sql' end,
         (select string_agg(policyname || ' (' || cmd || ')', ', ' order by policyname) from pg_policies where schemaname = 'storage' and tablename = 'objects' and policyname like 'campaign footage%'), 1
  union all
  select 'no policy lets apps change or remove files in the bucket',
         case when exists (select 1 from pg_policies where schemaname = 'storage' and tablename = 'objects' and (qual like '%campaign-footage%' or with_check like '%campaign-footage%') and policyname not in ('campaign footage read', 'campaign footage add')) then 'EXTRA POLICY: remove it' else 'ok' end,
         null, 1
  union all
  select 'limits in money_config',
         case when c.max_footage_seconds_total = 3600 and c.max_footage_seconds_each = 1800 then 'ok' else 'CHANGED from 60 / 30 minutes (fine if on purpose)' end,
         'total ' || c.max_footage_seconds_total || ' s, each ' || c.max_footage_seconds_each || ' s, ' || c.max_footage_bytes || ' bytes, removed ' || c.footage_delete_days || ' days after close, unused uploads ' || c.orphan_footage_days || ' days, agreement version ' || c.agreement_version, 2
    from public.money_config c
  union all
  select 'the database functions the footage screens call',
         case when (select count(*) from pg_proc p where p.pronamespace = 'public'::regnamespace
                      and p.proname in ('money_footage_register', 'money_footage_complete', 'money_footage_fail', 'money_footage_remove', 'money_create_campaign_with_footage')
                      and has_function_privilege('authenticated', p.oid, 'execute')) = 5 then 'ok' else 'MISSING or not executable: run migration-money-footage.sql' end,
         null, 2
  union all
  select 'the daily purge is scheduled',
         case when exists (select 1 from cron.job where jobname = 'money-footage-purge') then 'ok' else 'NOT SCHEDULED: run select public.money_footage_purge() by hand now and then' end,
         (select schedule from cron.job where jobname = 'money-footage-purge'), 2
  union all
  select 'the old Drive-link way of posting a campaign is closed',
         case when exists (select 1 from pg_proc where pronamespace = 'public'::regnamespace and proname = 'money_create_campaign' and prosrc like '%footage is uploaded now%') then 'ok'
              else 'OLD VERSION: run migration-money-board.sql again, then migration-money-footage.sql' end,
         null, 2
  union all
  select 'footage rows by status (counts only)', 'info',
         coalesce((select string_agg(status || ': ' || n, ', ' order by status) from (select status, count(*) n from public.campaign_footage group by status) t), 'none yet'), 3
  union all
  select 'files waiting for the removal job (media removal)', 'info',
         (select count(*) from public.trial_media_delete_queue where bucket = 'campaign-footage' and deleted_at is null)::text, 3
) x
order by (status in ('ok', 'info')), grp, check_name
  ) f
  union all
  select 'functions', check_name, status, trim(coalesce(used_by, '') || ' ' || coalesce(arguments, '')), 2 from (
select check_name, used_by, status, arguments
from (
  select f.fn as check_name, f.used_by,
         case when p.oid is null then 'MISSING'
              when not has_function_privilege('authenticated', p.oid, 'execute') then 'NO EXECUTE FOR APPS'
              else 'ok' end as status,
         pg_get_function_identity_arguments(p.oid) as arguments,
         1 as grp
    from (values
      ('my_features',               'app launch: whether the tab shows, the birthdate prompt (migration-money.sql, replaced by migration-money-board.sql)'),
      ('my_money_profile',          'Money tab: role and walkthrough state (migration-money-board.sql)'),
      ('money_complete_onboarding', 'walkthrough: "I agree" (migration-money-board.sql)'),
      ('money_create_campaign_with_footage', 'Post a campaign with its uploaded footage (migration-money-footage.sql)'),
      ('money_footage_register',    'Add footage: reserve the minutes and the file paths (migration-money-footage.sql)'),
      ('money_footage_complete',    'Add footage: the upload finished (migration-money-footage.sql)'),
      ('money_footage_fail',        'Add footage: an upload that was given up on (migration-money-footage.sql)'),
      ('money_footage_remove',      'Add footage: remove a video (migration-money-footage.sql)'),
      ('money_join_campaign',       'campaign: "I''m in" (migration-money-board.sql)'),
      ('money_set_campaign_status', 'campaign: Close campaign (migration-money-board.sql)'),
      ('campaign_payment_info',     'campaign: how you get paid, for members (migration-money-board.sql)'),
      ('money_profile_stats',       'cards: rating and payment record (migration-money-board.sql)'),
      ('set_my_birthdate',          'the birthdate prompt (migration-money.sql)'),
      ('my_birthdate',              'profile query: your own birthdate (migration-money.sql)')
    ) as f(fn, used_by)
    left join pg_proc p on p.pronamespace = 'public'::regnamespace and p.proname = f.fn
  union all
  select 'money_join_campaign is the latest version', 'campaign: "I''m in" also opens the message thread with the creator',
         case when exists (select 1 from pg_proc where pronamespace = 'public'::regnamespace and proname = 'money_join_campaign' and prosrc like '%I joined your campaign%')
              then 'ok' else 'OLD VERSION: run migration-money-board.sql again' end,
         null, 2
  union all
  select 'footage bucket (private)', 'Add footage: the private bucket the videos are uploaded to',
         case when exists (select 1 from storage.buckets where id = 'campaign-footage' and public = false)
              then 'ok' else 'MISSING: run migration-money-footage.sql' end,
         null, 2
  union all
  select 'campaigns table + budget_left column', 'Browse and the cards',
         case when to_regclass('public.campaigns') is not null
                and exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'campaigns' and column_name = 'budget_left')
              then 'ok' else 'MISSING: run migration-money-board.sql' end,
         null, 2
  union all
  select 'birthdate can be saved in the app', 'the birthdate prompt: set_my_birthdate refuses until the lock-down is applied',
         case when has_column_privilege('authenticated', 'public.profiles', 'birthdate', 'select')
              then 'NOT YET: the lock-down is not applied, so the app says "this isn''t available yet". For testing, set your own birthdate in SQL.'
              else 'ok (lock-down applied)' end,
         null, 3
) x
order by (status like 'ok%'), grp, check_name
  ) g
) c
order by (status in ('ok', 'info')), o1, check_name;
